#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Finite author packet. Writes only below this script's package directory."""
import hashlib
import json
from pathlib import Path

ROOT = Path.cwd()
OUT = Path(__file__).resolve().parents[1]
REL = OUT.relative_to(ROOT).as_posix()
CAN = 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-14/chemie-acid7-two-description-one-image-current419-native-successor-technical-20261014-v3/candidate/canonical551.current419.three-author-deltas.exact.json'
SEM = CAN.rsplit('/', 1)[0] + '/semantic551.current419.only-two-kind-source-bindings.stock-helper.json'
CLAIM = 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-12/chemie-current402-all182-open-claims-root-20261012-v2/claims/laboratory-communication-15.current402.claim.config.json'
NEUTRAL = 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-14/chemie-acid7-current419-paired-D6-retained059-P7A7M2V1-inactive-integration-technical-20261014-v4/NEUTRAL.final-inactive-integration-and-physical-resume.json'

def read(p): return json.loads((ROOT / p).read_text())
def digest(p):
    b = (ROOT / p).read_bytes()
    return {'path': p, 'sha256': 'sha256:' + hashlib.sha256(b).hexdigest(), 'bytes': len(b)}
def write(p, x):
    q = OUT / p
    q.parent.mkdir(parents=True, exist_ok=True)
    q.write_text(json.dumps(x, ensure_ascii=False, indent=2) + '\n')

landscape = read(CAN)
goals = {g['id']: g for g in landscape['goals']}
ids = read(CLAIM)['goalIds']
assert len(ids) == len(set(ids)) == 15
assert digest(CAN)['sha256'] == 'sha256:b07e023f03a7c573e2b823c491e030c0ca1b5d530b17116de2b4a3d8010d0339'
cases = []
designs = []

def bilingual(de, en): return {'de': de, 'en': en}

def case(n, suffix, title_de, title_en, materials_de, materials_en, protocol_de, protocol_en,
         task_de, task_en, solution_de, solution_en, rubric_de, rubric_en, change_de, change_en,
         practical=True):
    """All content arguments below are manually authored, not generated from goal titles."""
    assert len(rubric_de) == len(rubric_en) == 4
    c = {
        'caseId': f'lab15-{n:02d}-{suffix}', 'goalId': ids[n-1],
        'title': bilingual(title_de, title_en),
        'provenance': bilingual('Eigenes fiktives Lehrmodell; Zahlen sind konstruierte Übungsdaten, keine Messung und kein offizieller Lehrplantext.',
                                'Original fictional teaching model; numbers are constructed practice data, not measurements or official curriculum text.'),
        'imageDependency': 'none',
        'materialsAndSuppliedData': bilingual(materials_de, materials_en),
        'protocolAndConditions': bilingual(protocol_de, protocol_en),
        'actualTask': bilingual(task_de, task_en),
        'expectedReasoningAndSolution': bilingual(solution_de, solution_en),
        'freshIndependentTransfer': bilingual(change_de, change_en),
        'criterionToObservableRubric': [
            {'expectationId': f'e{k+1}', 'criterionAndObservable': bilingual(d, e),
             'futureObservation': None, 'met': None}
            for k, (d, e) in enumerate(zip(rubric_de, rubric_en))
        ],
        'assessmentMode': 'future-observed-practical-performance-plus-reasoning' if practical else 'future-independent-written-or-oral-performance',
        'executionStatus': 'not-executed-author-design',
        'futureObservationRecord': {
            'date': None, 'conditions': None, 'apparatusAndMaterials': None,
            'riskControlsApplied': None, 'actualStepsAndAdaptations': None,
            'rawObservationsAndUnits': None, 'replicatesAndUncertainty': None,
            'deviationsAndLimitations': None, 'learnerExplanation': None,
            'observedPracticalPerformance': None, 'assessmentDecision': None,
        },
        'evidenceBoundary': bilingual(
            'Das entworfene Material ist maschinell prüfbares Curriculum-QS-Material. Die Übungsdaten belegen keine ausgeführte Handlung. Wo der Zieloperator Ausführen, Herstellen oder Durchführen verlangt, verlangt die spätere Kompetenzbeurteilung beobachtbare tatsächliche Ausführung mit eigenem Protokoll. M7 setzt keine bereits erfolgte Lernendenerprobung voraus.',
            'The design is material for machine curriculum QA. Practice data do not demonstrate an executed action. Where the goal requires carrying out, producing or conducting, later competence assessment requires observable actual performance and an original record. M7 does not require an already completed learner trial.'),
    }
    cases.append(c)

def design(n, archetype, expectations, axis_de, axis_en, concern=None):
    # Each item supplies an exact understanding and a matching observable, in both languages.
    assert len(expectations) == 4
    designs.append({'goalId': ids[n-1], 'archetype': archetype,
        'expectations': [{'id': f'e{k+1}', 'essentialUnderstandingDe': a, 'essentialUnderstandingEn': b,
                          'observablePerformanceDe': c, 'observablePerformanceEn': d}
                         for k, (a,b,c,d) in enumerate(expectations)],
        'variationAxes': [{'id': 'chemically-meaningful-change', 'textDe': axis_de, 'textEn': axis_en}],
        'authorConcern': concern})

# 01 Basic laboratory methods. Both cases require handling, not a narrated simulation.
case(1,'a','Salzlösung dosieren und Sand abfiltrieren','Measure salt solution and filter sand',
 'Je Gruppe: Schutzbrille, Waage ±0,01 g, 50-mL-Messzylinder mit 1-mL-Teilung, Becher, Rührstab, Trichter, Filterpapier, Auffangbecher, 2,00 g Kochsalz, 1,00 g sauberer Sand, Wasser. Lehrdaten eines anderen Ansatzes: eingewogen 2,01 g Salz und 1,02 g Sand; abgelesen 20 mL Wasser; nach Rühren trüb; Filtrat klar, nasser Rückstand körnig.',
 'Per group: goggles, balance ±0.01 g, 50-mL cylinder with 1-mL divisions, beaker, rod, funnel, paper, receiver, 2.00 g sodium chloride, 1.00 g clean sand, water. Practice data from a different batch: 2.01 g salt and 1.02 g sand weighed; 20 mL water read; cloudy after stirring; clear filtrate and wet granular residue.',
 'Unter Aufsicht ohne Erhitzen: Gefäße beschriften; Waage mit Wägeschale tarieren; Stoffe getrennt wiegen; Wasser auf Augenhöhe am Meniskus ablesen; rühren; passendes Papier falten und benetzen; durch Trichter ohne Überfüllen filtrieren; Geräte reinigen. Schutzbrille, keine Geschmacksprobe; sauberen Sand nach örtlicher Anweisung sammeln. Zeit, Mengen und Beobachtungen sofort notieren.',
 'Supervised, without heating: label vessels; tare a weighing boat; weigh substances separately; read the meniscus at eye level; stir; fold and wet suitable paper; filter without overfilling; clean apparatus. Goggles, no tasting; collect clean sand according to local instructions. Record times, quantities and observations immediately.',
 'Führe den Ansatz aus und protokolliere deine tatsächlich verwendeten Mengen und Arbeitsschritte. Ordne die Lehrdaten getrennt als Vergleich ein. Erkläre, warum klares Filtrat nicht automatisch reines Wasser ist. Demonstriere anschließend eine eigene korrekte Volumenablesung, ohne die Zahl eines anderen abzuschreiben.',
 'Carry out the batch and record your actual quantities and actions. Mark supplied practice data separately for comparison. Explain why clear filtrate need not be pure water. Then demonstrate an independent correct volume reading without copying another person’s value.',
 'Die Waage misst Masse; der Zylinder das Flüssigkeitsvolumen. Der unten liegende Meniskus wird bei Wasser auf Augenhöhe gelesen. Sand bleibt wegen seiner Teilchengröße im Filter, gelöstes Salz passiert mit Wasser. Trübung und Klarheit sind Beobachtungen; gelöstes Salz ist eine begründete Deutung. Nasse Rückstandsmasse wäre keine trockene Sandmasse. Tatsächliche Geschicklichkeit und Dokumentation bleiben bis zur Ausführung unbeobachtet.',
 'The balance measures mass; the cylinder measures liquid volume. Read the bottom of a water meniscus at eye level. Sand is retained by particle size, while dissolved salt passes with water. Cloudiness and clarity are observations; dissolved salt is an inference. Wet residue mass is not dry sand mass. Actual handling and documentation remain unobserved until performance.',
 ['E1: Tara und Einwaage tatsächlich korrekt vorführen; notierte Masse mit Einheit statt abgeschriebener Sollmenge.', 'E2: Volumen auf Augenhöhe ablesen und Filter passend einsetzen; kein Überlaufen oder Vermischen beschrifteter Gefäße.', 'E3: Eigenes Protokoll enthält Reihenfolge und rohe Beobachtungen; Lehrdaten sind als fremde Übungsdaten markiert.', 'E4: Klarheit von Stoffreinheit unterscheiden und erklären, weshalb Salz durch den Filter gelangt.'],
 ['E1: Actually demonstrate taring and weighing; record mass with units rather than copying the target.', 'E2: Read at eye level and fit the filter; avoid overflow or mixing labelled vessels.', 'E3: Own record contains sequence and raw observations; practice data are marked as external.', 'E4: Distinguish clarity from purity and explain why salt passes through paper.'],
 'Ein neuer Ansatz enthält statt Sand löslichen Zucker. Wähle selbst, ob Filtration noch einen Rückstand liefern sollte, und führe einen entsprechend begründeten Kontrollansatz aus.',
 'A fresh batch contains soluble sugar instead of sand. Independently decide whether filtration should retain a solid and carry out a justified control.')
case(1,'b','Dekantieren und präzise umfüllen','Decant and transfer carefully',
 'Schutzbrille, 2 Becher, Pasteurpipette mit Saugball, 25-mL-Messzylinder, 2,0 g gewaschener Kies, 15 mL Wasser, Waage ±0,01 g. Übungsbeobachtungen: nach Schwenken bewegte Teilchen; nach 2 min abgesetzt; beim schnellen Gießen wandern Körner in das zweite Gefäß; langsames Gießen entlang des Stabes vermeidet dies weitgehend.',
 'Goggles, two beakers, dropper with bulb, 25-mL cylinder, 2.0 g washed gravel, 15 mL water, balance ±0.01 g. Practice observations: moving particles after swirling; settled after two minutes; fast pouring transfers grains; slow pouring along a rod largely avoids this.',
 'Unter Aufsicht Kies und Wasser mischen und 2 min stehen lassen. Etwa 10 mL Überstand langsam dekantieren, ohne alles abzugießen. Eine kleine Restmenge mit Saugballpipette übertragen; niemals mit dem Mund pipettieren. Volumen vor und nach dem Übertragen ablesen und Verluste dokumentieren; keine erhitzten oder unbekannten Flüssigkeiten.',
 'Under supervision, mix gravel and water and leave for two minutes. Slowly decant about 10 mL of supernatant, leaving some liquid behind. Transfer a small remainder with a bulb dropper; never mouth pipette. Read volumes before and after transfer and document losses; no heated or unknown liquids.',
 'Zeige Dekantieren und dosiertes Pipettieren selbst. Notiere die tatsächlich übertragenen Volumina, unerwünschte Körner und Restflüssigkeit. Begründe die Wahl gegenüber sofortigem kräftigem Ausgießen. Kannst du aus zurückbleibender Flüssigkeit auf falsche Volumenablesung schließen?',
 'Demonstrate decanting and controlled pipetting yourself. Record actual transferred volumes, unwanted grains and residual liquid. Justify the choice over immediate vigorous pouring. Does residual liquid prove an incorrect volume reading?',
 'Absetzen ermöglicht die Trennung eines Überstands von großen dichten Körnern; Flüssigkeitsreste sind beabsichtigt und beschränken Rückgewinnung. Eine Tropfpipette dosiert, ist aber kein kalibriertes Präzisionsmessgerät. Restflüssigkeit allein beweist keinen Ablesefehler; Benetzung, bewusster Rest und Verschütten sind verschieden. Eigenes Protokoll muss reale Abweichungen enthalten.',
 'Settling allows supernatant to be separated from large dense grains; leaving liquid is intentional and limits recovery. A dropper dispenses but is not a calibrated precision measuring device. Residual liquid alone does not prove a reading error; wetting, a deliberate remainder and spillage differ. The original record must retain actual deviations.',
 ['E1: Geeignete Geräte bereitstellen, beschriften und Messbereich passend wählen.', 'E2: Absetzen, langsames Abgießen und Saugballpipette tatsächlich sachgerecht zeigen.', 'E3: Übertragenes Volumen und Rest mit Einheit sowie Verluste unmittelbar dokumentieren.', 'E4: Begründen, warum fehlende vollständige Rückgewinnung und ungenaue Tropfenzahl keine sichere Messfehlerdiagnose erlauben.'],
 ['E1: Prepare and label suitable apparatus and choose an appropriate range.', 'E2: Actually demonstrate settling, slow decanting and bulb pipetting.', 'E3: Immediately record transferred and residual volumes with units and losses.', 'E4: Explain why incomplete recovery and an imprecise drop count do not uniquely diagnose a reading error.'],
 'Erhalte frisch ein Gemisch mit fein verteiltem Sand, das nach 2 min noch trüb ist. Entscheide ohne Methodenvorgabe, wie du klares Wasser gewinnst, und demonstriere die angepasste Handhabung.',
 'Receive a fresh mixture of fine sand still cloudy after two minutes. Without a method cue, choose how to obtain clear liquid and demonstrate the adapted handling.')

# 02 Alcohol risk: complete informational cards, no drinking trial or dose advice.
case(2,'a','Fest und Heimweg beurteilen','Assess a celebration and the journey home',
 'Fiktive Sachkarten, keine Individualdiagnose: K1 Ethanol kann Aufmerksamkeit, Koordination und Urteilsvermögen beeinträchtigen; eigenes Nüchternheitsgefühl ist kein verlässlicher Funktionstest. K2 Wiederholter Konsum kann Organe schädigen und Abhängigkeit begünstigen; Risiko hängt unter anderem von Menge, Muster und Person ab. K3 Verfügbarkeit, Gruppendruck, Stressbewältigung und Gewöhnung können zusammenwirken; Abhängigkeit ist keine bloße Willensschwäche. Situation: Bei einer Schulfeier soll eine Person nach alkoholhaltigen Getränken mit dem Rad heimfahren; andere sagen, Kaffee und frische Luft machten sofort wieder sicher.',
 'Fictional information cards, not an individual diagnosis: C1 Ethanol can impair attention, coordination and judgement; feeling sober is not a reliable functional test. C2 Repeated consumption can damage organs and promote dependence; risk depends on amount, pattern and person among other factors. C3 Availability, peer pressure, coping with stress and habituation can interact; dependence is not simply weak will. Scenario: after alcoholic drinks at a school celebration a person plans to cycle home; peers claim coffee and fresh air immediately restore safety.',
 'Keine Einnahme, keine Promilleberechnung, keine personenbezogenen Fragen. Verwende ausschließlich die bereitgestellten Karten als Sachbasis. Trenne akute Wirkung, langfristige Schädigung, soziale Einflussfaktoren und Entscheidungskriterien. Formuliere einen schulischen Sicherheitsvorschlag, keine medizinische Behandlung.',
 'No ingestion, blood-alcohol calculation or personal disclosure. Use the supplied cards as the information basis. Separate acute effects, long-term harm, social influences and decision criteria. Propose a school safety response, not medical treatment.',
 'Prüfe die Kaffee-Behauptung an den Karten. Begründe eine sichere Heimwegentscheidung und zwei Maßnahmen der Feierorganisation. Erkläre, wie Gruppendruck und wiederholtes Trinken einander verstärken können, ohne Betroffene abzuwerten. Benenne eine Aussage, die die Karten nicht erlauben.',
 'Assess the coffee claim using the cards. Justify a safe journey decision and two organisational measures. Explain how peer pressure and repeated drinking can reinforce one another without stigmatising people. Name one conclusion not supported by the cards.',
 'Die Behauptung liefert keinen verlässlichen Nachweis wiederhergestellter Fähigkeiten; Gefühl ersetzt keinen Funktionstest. Geeignet ist ein Heimweg ohne eigene Verkehrsteilnahme, etwa Abholung durch eine verlässlich nüchterne Begleitperson. Alkoholfreie Angebote und früh geplante Heimwege senken situative Anreize und Risiken. Organrisiko, akute Beeinträchtigung und Abhängigkeitsentstehung sind verschiedene Ebenen. Aus den Karten folgen weder individuelle Diagnose noch eine sichere Menge oder minutengenaue Erholung.',
 'The claim gives no reliable evidence of restored ability; subjective feeling is not a functional test. Choose travel without operating a vehicle, such as collection by a reliably sober accompanying person. Alcohol-free options and advance travel plans reduce situational incentives and risks. Organ harm, acute impairment and development of dependence are distinct levels. The cards support no personal diagnosis, safe dose or exact recovery time.',
 ['E1: Akute Koordinations-/Urteilsbeeinträchtigung und mögliche langfristige Organschäden getrennt erklären.', 'E2: Mindestens zwei zusammenwirkende soziale oder individuelle Abhängigkeitsfaktoren ohne monokausale Schuldzuweisung verbinden.', 'E3: Heimweg und Organisation anhand benannter Sicherheitskriterien begründet auswählen.', 'E4: Kaffee-Behauptung begrenzt zurückweisen und individuelle Mengen-/Zeitdiagnosen ausdrücklich als unbelegt markieren.'],
 ['E1: Separately explain acute coordination/judgement impairment and possible long-term organ harm.', 'E2: Connect at least two interacting social or individual dependence factors without assigning single-cause blame.', 'E3: Select journey and organisational measures using explicit safety criteria.', 'E4: Reject unsupported coffee reasoning and mark individual dose/time diagnoses as unsupported.'],
 'Eine neue Situation betrifft keinen Heimweg, sondern wiederholtes Trinken als angeblich einziges Mittel gegen Prüfungsstress. Entwickle ohne vorgegebene Antwort eine begründete Präventionsentscheidung und grenze Hilfe von Stigmatisierung ab.',
 'A fresh scenario concerns repeated drinking as an allegedly unique way to manage exam stress. Independently develop a reasoned prevention response and distinguish support from stigma.',False)
case(2,'b','Werbekampagne und Abhängigkeitsursachen','Advertising and causes of dependence',
 'Fiktive Karten: A Alkohol ist ethanolhaltig; chemische Reinheit oder natürliche Herkunft beseitigen seine möglichen körperlichen Wirkungen nicht. B Häufigkeit und Trinkmuster beeinflussen Belastung; Langzeitfolgen und akute Unfallgefahren sind zu unterscheiden. C Biologische Empfindlichkeit, Lernprozesse, Belastungen, soziale Normen und leichte Verfügbarkeit können Abhängigkeitsentwicklung gemeinsam beeinflussen. D Bei bestehenden Problemen ist respektvolle professionelle Unterstützung sinnvoll; Schuldzuweisung erklärt die Ursachen nicht. Zwei fiktive Plakate: P „Natürlich vergoren, deshalb gesundheitlich unbedenklich“; Q „Wer Hilfe braucht, ist selbst schuld“. Keine Zahlen zu Dosis oder Häufigkeit sind angegeben.',
 'Fictional cards: A Alcoholic products contain ethanol; chemical purity or natural origin do not remove its potential physical effects. B Frequency and drinking patterns influence exposure; distinguish long-term effects from acute accident hazards. C Biological sensitivity, learning processes, stress, social norms and availability can interact in dependence. D Respectful professional support is appropriate for existing problems; blame does not explain causes. Fictional posters: P “Naturally fermented, therefore harmless”; Q “People needing help have only themselves to blame”. No dose or frequency figures are given.',
 'Arbeite mit den Karten und Plakatwortlauten; keine Recherche über Mitschüler, kein Selbsttest. Erstelle eine begründete Gegenposition für eine schulische Ausstellung. Belege jede Sachaussage durch Kartenkennung und markiere zusätzliche Wertkriterien.',
 'Use the cards and poster wording; no research on classmates and no self-testing. Prepare a reasoned response for a school exhibition. Link each factual statement to a card and mark additional value criteria.',
 'Korrigiere beide Plakate fachlich und respektvoll. Erkläre für ein jugendliches Publikum körperliche Schädigung, situative Gefährdung und mehrere Abhängigkeitsursachen. Wähle für eine Veranstaltung zwischen leichter Alkoholwerbung und alkoholfreiem Angebot und begründe die Kriterien. Welche konkrete Risikozahl fehlt?',
 'Correct both posters accurately and respectfully. Explain physical harm, situational danger and multiple causes of dependence to a young audience. Choose between easy alcohol promotion and alcohol-free provision for an event and justify criteria. What specific risk figure is missing?',
 'P verwechselt Herkunft mit Wirkung; auch Gärung erzeugt Ethanol. Q ignoriert das Zusammenspiel von Empfindlichkeit, Lernen und Umfeld. Die Entscheidung kann Sicherheit und gleichberechtigte Teilnahme priorisieren; alkoholfreie Angebote vermeiden Konsumdruck. Eine nach Häufigkeit oder Person quantifizierte Risikoprognose ist ohne Daten nicht berechenbar. Gesundheitliche Gründe sind nicht mit moralischen Urteilen über Betroffene gleichzusetzen.',
 'P confuses origin with effects; fermentation also produces ethanol. Q ignores interacting sensitivity, learning and environment. The decision may prioritise safety and inclusive participation; alcohol-free provision avoids pressure to consume. A person-specific or frequency-specific risk estimate cannot be calculated from missing data. Health reasoning is different from moral judgement of affected people.',
 ['E1: Natürliche Herkunft nicht mit fehlender Ethanolwirkung verwechseln; akute und chronische Gefährdung unterscheiden.', 'E2: Biologische, psychische und soziale Ursachen als Zusammenspiel statt persönlicher Schuld darstellen.', 'E3: Eine konkrete Veranstaltungsentscheidung mit transparenten Gesundheits- und Teilhabekriterien begründen.', 'E4: Fehlende Risikoquantifizierung offenlegen und keine vermeintlich sichere Konsummenge erfinden.'],
 ['E1: Do not confuse natural origin with absence of ethanol effects; distinguish acute and chronic risks.', 'E2: Present biological, psychological and social factors as interacting rather than personal fault.', 'E3: Justify a concrete event decision using transparent health and inclusion criteria.', 'E4: Disclose missing risk quantification and do not invent a safe amount.'],
 'Prüfe frisch eine Werbung, die „alkoholarm“ ohne Angabe von Gehalt, Menge oder Zielgruppe als risikofrei bezeichnet. Entscheide eigenständig, welche Informationen und Kriterien für ein Urteil fehlen.',
 'Assess fresh advertising that calls “low alcohol” risk-free without specifying content, amount or audience. Independently decide what information and criteria are missing.',False)

# 03 Advanced methods: two complete portfolios rather than reducing the goal to one test.
case(3,'a','Präparationsportfolio: Zwiebel und Calciumcarbonat','Preparation portfolio: onion and calcium carbonate',
 'Brille, Handschuhe nach örtlicher Vorgabe, Objektträger/Deckglas, Zwiebel, Wasser, Mikroskop; getrennte Chemiearbeitsfläche mit 10,0 mL 0,100 mol/L CaCl2 und 10,0 mL 0,100 mol/L Na2CO3, Pipettierhilfe, Filter, Waage ±0,01 g. M(CaCO3)=100,1 g/mol. Fiktive Fremddaten: weißer Niederschlag; trockener Feststoff 0,09 g; Blindprobe Wasser+CaCl2 klar.',
 'Goggles, gloves as locally required, slide/coverslip, onion, water, microscope; separate chemistry bench with 10.0 mL 0.100 mol/L CaCl2 and 10.0 mL 0.100 mol/L Na2CO3, pipette aid, filter, balance ±0.01 g. M(CaCO3)=100.1 g/mol. Fictional external data: white precipitate; dry solid 0.09 g; water+CaCl2 blank clear.',
 'Unter fachlicher Aufsicht zuerst dünne Zwiebelepidermis als Wasserpräparat ohne Färbung einbetten; Deckglas schräg auflegen, bei kleiner Vergrößerung beginnen. Separat Lösungen abmessen, mischen, Niederschlag filtrieren, mit zweimal 2 mL Wasser waschen und bei Raumtemperatur bis zur Massenkonstanz trocknen. Geräte für Biologie und Chemie getrennt halten; kein Essen, kein Mundpipettieren, Glasbruch vermeiden; Abfälle örtlich sammeln.',
 'Under qualified supervision prepare thin onion epidermis in water without stain; lower coverslip at an angle and start at low magnification. Separately measure and mix solutions, filter precipitate, wash twice with 2 mL water and dry at room temperature to constant mass. Keep biological and chemical apparatus separate; no food or mouth pipetting, avoid glass breakage; collect waste locally.',
 'Plane die beiden Stationen mit getrennten Kontrollen. Führe Präparation, qualitative Beobachtung und quantitative Fällung/Aufarbeitung tatsächlich aus. Dokumentiere Originaldaten und begründe jeden Gerätewechsel. Prüfe am Fremdbeispiel, ob 0,09 g eine exakte Ausbeute zulässt.',
 'Plan both stations with separate controls. Actually perform preparation, qualitative observation and quantitative precipitation/work-up. Document original data and justify apparatus choices. Assess whether the external 0.09 g result permits an exact yield.',
 'Die Zwiebelpräparation benötigt eine dünne, nicht überlappende Probe; Blasen sind Artefakte. Ca2+ + CO3^2− → CaCO3(s) erhält Atome/Ladung. Je 1,00 mmol ergeben theoretisch 0,1001 g, 0,09 g entsprächen grob 90%; ±0,01 g Wägeauflösung begrenzt die Aussage stark. Waschen entfernt lösliche Salze, Trocknen verhindert Wasser als Scheinprodukt. Fremddaten beweisen keine eigene Durchführung.',
 'Onion preparation requires a thin, non-overlapping sample; bubbles are artefacts. Ca2+ + CO3^2− → CaCO3(s) conserves atoms/charge. Each reagent supplies 1.00 mmol, giving 0.1001 g theoretical solid; 0.09 g is roughly 90%, limited strongly by ±0.01 g balance resolution. Washing removes soluble salts and drying prevents water being counted as product. External data prove no own performance.',
 ['E1: Biologischen Dünnschnitt und quantitatives Fällungsverfahren mit passenden Geräten eigenständig planen.', 'E2: Präparieren, Pipettieren, Filtrieren/Waschen und Kreuzkontaminationsschutz tatsächlich beobachten lassen.', 'E3: Rohbeobachtung, Mengen und Massenkonstanz getrennt mit Einheiten protokollieren.', 'E4: Kontrollprobe, Ladungsbilanz und begrenzte Ausbeutegenauigkeit fachlich erklären.'],
 ['E1: Independently plan biological thin preparation and quantitative precipitation with suitable apparatus.', 'E2: Make actual preparation, pipetting, filtering/washing and contamination control observable.', 'E3: Separately record raw observations, quantities and constant mass with units.', 'E4: Explain the blank, charge balance and limited yield precision.'],
 'Frisch wird die Carbonatlösung halb so konzentriert angeboten. Wähle ohne Rechenmuster Stoffmengen und Kontrollansatz neu und begründe, warum eine nasse Masse über der theoretischen Trockenmasse keine bessere Synthese beweist.',
 'Fresh carbonate solution has half the concentration. Independently select amounts and controls and explain why wet mass above theoretical dry mass does not demonstrate improved synthesis.')
case(3,'b','Präparationsportfolio: Enzymextrakt und Gelkügelchen','Preparation portfolio: enzyme extract and gel beads',
 'Brille, Reibe, Filter, 5,0 g frische Kartoffel, 20 mL Wasser, Mikroskop und Objektträger; getrennt 10 mL 1% Natriumalginat und 30 mL 1% CaCl2, Tropfpipette, Sieb, Waage. Qualitative Aktivitätsstation: je 2 mL höchstens1% H2O2 mit 1 mL frischem bzw. von der Lehrkraft erhitztem/abgekühltem Extrakt. Fremdbeispiel: frischer Extrakt blubbert, erhitzter kaum; 20 Gelkugeln nach 30 s stärker verformbar als nach 180 s.',
 'Goggles, grater, filter, 5.0 g fresh potato, 20 mL water, microscope and slides; separately 10 mL 1% sodium alginate and 30 mL 1% CaCl2, dropper, sieve, balance. Qualitative activity station: 2 mL at most1% H2O2 plus 1 mL fresh or teacher-heated/cooled extract. External example: fresh extract bubbles, heated extract scarcely does; 20 beads deform more after 30 s than after 180 s.',
 'Nur unter Laboraufsicht, H2O2 nicht auf Haut/Augen, Kartoffel nicht verzehren. Kartoffel mit Wasser zerkleinern, filtrieren; dünnes Materialpräparat herstellen. Extraktaktivität mit Wasserblindprobe vergleichen, kleine offene Gefäße nutzen. Alginat langsam in CaCl2 tropfen, zwei gleiche Gruppen 30/180 s belassen, sieben, zweimal mit Wasser spülen, je 20 Kugeln abtupfen und wiegen. Abfälle getrennt sammeln.',
 'Only under laboratory supervision; keep H2O2 from skin/eyes, no consumption. Disrupt potato in water and filter; make a thin material preparation. Compare extract activity with a water blank in small open vessels. Drop alginate into CaCl2, keep two equal groups for 30/180 s, sieve, rinse twice, blot and weigh 20 beads per group. Collect waste separately.',
 'Erstelle und führe einen Arbeitsplan für Extraktion, mikroskopisches Präparat, qualitative Aktivitätsprüfung und quantitative Gelpräparation aus. Lege vergleichbare Tropfen und Abtupfbedingungen fest. Erkläre, welche Stoffumwandlung oder Strukturänderung jeweils untersucht wird und was die Fremddaten nicht beweisen.',
 'Create and execute a plan for extraction, microscopic preparation, qualitative activity testing and quantitative gel preparation. Set comparable drop and blotting conditions. Explain the chemical or structural change at each station and what external data cannot prove.',
 'Filtration gewinnt gelöste/bzw. fein verteilte Enzymbestandteile, kein reines Enzym. Katalase beschleunigt 2H2O2 → 2H2O + O2; Blasen allein sind ohne Blindprobe unspezifisch. Ca2+ vernetzt Alginat, keine Herstellung neuer Ketten. Gleiche Kugelzahl bedeutet ohne Tropfengrößenkontrolle keine gleiche Masse. Erhitzung und pH können Aktivität verändern; gezeichnete Strukturen ersetzen kein selbst hergestelltes Präparat.',
 'Filtration obtains dissolved/fine enzyme components, not pure enzyme. Catalase accelerates 2H2O2 → 2H2O + O2; bubbles alone are nonspecific without a blank. Ca2+ crosslinks alginate rather than producing new chains. Equal bead counts do not ensure equal mass without drop-size control. Heat and pH can affect activity; drawn structures do not replace an original specimen.',
 ['E1: Unterschiedliche Präparations-/Untersuchungszwecke mit eigenem vollständigem Plan verbinden.', 'E2: Extraktion, Präparat und Gelaufarbeitung mit geeigneter Stofftrennung und Sicherheit tatsächlich ausführen.', 'E3: Tropfenbedingungen, Kontrollansätze, Kugelzahl, Masse und qualitative Beobachtung getrennt dokumentieren.', 'E4: Enzymreaktion und ionische Vernetzung unterscheiden; Reinheit und biologische Allgemeingültigkeit begrenzen.'],
 ['E1: Link distinct preparation/investigation purposes in an original complete plan.', 'E2: Actually execute extraction, specimen preparation and gel work-up with suitable separation and safety.', 'E3: Separately record drop conditions, controls, bead count, mass and qualitative observations.', 'E4: Distinguish enzyme reaction from ionic crosslinking; limit purity and biological generalisations.'],
 'Ein frischer farbiger Extrakt schäumt auch ohne H2O2. Entwirf unabhängig neue Blindkontrollen und ändere die qualitative Messgröße, statt Schaum automatisch als Enzymaktivität zu zählen.',
 'A fresh coloured extract foams even without H2O2. Independently devise new blanks and change the qualitative outcome instead of automatically counting foam as enzyme activity.')

# 04 Communication of actual supplied investigations.
case(4,'a','Leitfähigkeit für Fachpublikum und Eltern darstellen','Present conductivity to specialists and parents',
 'Fiktive Messreihe bei 20°C, gleiche Zelle: Wasser 5/6 µS/cm, 0,010 mol/L NaCl 1190/1210 µS/cm, 0,010 mol/L Saccharose 9/10 µS/cm. Zwei Wiederholungen, Gerätebereich bis2000 µS/cm, Auflösung1 µS/cm; Proben nicht auf vollständige Reinheit geprüft. Zielgruppen: Chemie-AG und Elternabend, je90 s.',
 'Fictional series at20°C, same cell: water5/6 µS/cm, 0.010 mol/L NaCl1190/1210 µS/cm, 0.010 mol/L sucrose9/10 µS/cm. Two repeats; range up to2000 µS/cm, resolution1 µS/cm; full purity not tested. Audiences: chemistry club and a parents’ meeting,90 s each.',
 'Nutze nur die mitgelieferten Zahlen; kein eigener Versuch nötig für dieses Darstellungsziel. Rohwerte erhalten, Mittelwerte kennzeichnen; Nullpunkt und Skalierung offenlegen. Teilchenaussagen als Modell erklären, nicht als beobachtete Ionenbilder.',
 'Use the supplied numbers; this representation goal needs no new experiment. Retain raw values and label means; disclose zero and scaling. Mark particle statements as a model rather than observed pictures of ions.',
 'Erstelle eine beschriftete Tabelle plus passende Grafik für die AG und einen verständlichen Text für Eltern. Begründe die Formwahl und einen Informationsverlust der Kurzfassung. Prüfe die Aussage „Alles Gelöste leitet gleich gut“.',
 'Create a labelled table and suitable chart for the club plus an accessible text for parents. Justify each format and one loss in the short version. Assess “Everything dissolved conducts equally well”.',
 'Mittelwerte5,5;1200;9,5 µS/cm. Ein Säulendiagramm eignet sich für die diskreten Proben; Wiederholungen/Spannweiten müssen erkennbar bleiben. NaCl-Lösung leitet im Modell wegen beweglicher Ionen wesentlich stärker; Saccharose bleibt überwiegend ungeladen. Messwerte allein zeigen keine Ionen. Die Elternfassung darf Einheiten erklären, aber Vergleichsbedingungen und geringe Datenzahl nicht verschweigen.',
 'Means5.5,1200,9.5 µS/cm. A bar chart suits discrete samples and should retain repeats/ranges. In the model, NaCl conducts much more strongly because of mobile ions; sucrose remains largely uncharged. Readings do not directly show ions. The parents’ version may explain units but must retain comparison conditions and the small dataset.',
 ['E1: Alle sechs Rohwerte und Bedingungen korrekt in die Darstellung übertragen.', 'E2: Mittelwerte, Achsen, Einheiten und Probenbezeichnungen eindeutig darstellen.', 'E3: Fachliche und allgemeinverständliche Fassung sachgerecht auf jeweilige Adressaten ausrichten.', 'E4: Formwahl und ausgelassene Information begründen; Beobachtung und Ionenmodell sprachlich unterscheiden.'],
 ['E1: Accurately transfer all six raw values and conditions.', 'E2: Unambiguously label means, axes, units and samples.', 'E3: Adapt specialist and accessible versions appropriately to each audience.', 'E4: Justify format and omissions; distinguish observation from the ion model.'],
 'Eine neue Probe überschreitet den Gerätebereich. Stelle die Information ohne erfundene Zahl dar und wähle für einen Elternhinweis eine ehrliche Formulierung.',
 'A fresh sample exceeds the instrument range. Represent that information without inventing a number and choose honest wording for parents.',False)
case(4,'b','Temperaturverläufe ohne Kausalitätsübertreibung','Temperature series without overclaiming causation',
 'Fiktiver Vergleich, offene Becher, jeweils50,0 g Wasser, Raum20°C, Start20,0°C. Nach Zugabe von2,00 g Stoff: t=0/30/60/120 s; X=20,0/24,0/23,5/22,0°C; Y=20,0/16,0/16,5/18,0°C. Fühler±0,5°C; keine Wiederholung, kein Kalorimeter. Schulausstellung soll erklären, ein Fachprotokoll soll Grenzen dokumentieren.',
 'Fictional comparison in open beakers,50.0 g water each, room20°C, start20.0°C. After adding2.00 g material: t=0/30/60/120 s; X=20.0/24.0/23.5/22.0°C; Y=20.0/16.0/16.5/18.0°C. Probe±0.5°C; no replication, no calorimeter. An exhibition should explain; a technical record should document limits.',
 'Die Stoffe bleiben anonym; keine unbekannten Stoffe praktisch mischen. Wähle ein Zeitdiagramm und eine textliche Kurzfassung; unterscheide Datenpunkte von interpolierten Linien und Energieerklärung.',
 'Keep materials anonymous; do not physically mix unknown substances. Choose a time chart and a short text; distinguish data points, interpolated lines and energy explanation.',
 'Erstelle die zwei adressatengerechten Produkte einschließlich Datenherkunft. Erkläre, warum ein Kreisdiagramm ungeeignet wäre. Prüfe, ob die Daten eine exakte Reaktionsenthalpie oder die Behauptung „Y bleibt immer kalt“ tragen.',
 'Create both audience-appropriate products with data provenance. Explain why a pie chart is unsuitable. Assess whether these data support exact reaction enthalpy or “Y remains cold forever”.',
 'Zeit ist unabhängige Achse, Temperatur abhängige; gleiche Skala macht Erwärmung und Abkühlung vergleichbar. Nach120 s nähern sich beide der Raumtemperatur; Wärmeaustausch ist plausibel. Reaktionsenthalpie braucht Systemgrenze, Wärmekapazitäten und Verluste; die einzelnen Temperaturwerte allein genügen nicht. Im Ausstellungstext bleibt „in diesem Versuch“ erhalten.',
 'Time is independent and temperature dependent; a shared scale permits comparison of warming/cooling. At120 s both approach room temperature; heat exchange is plausible. Reaction enthalpy needs system boundaries, heat capacities and loss corrections; isolated temperatures are insufficient. The exhibition text retains “in this trial”.',
 ['E1: Beide vollständigen Reihen samt Fühlerunsicherheit ohne Zahlenverwechslung übertragen.', 'E2: Zeitdiagramm mit gleichen Skalen, Einheiten und als Verbindung markierten Linien erstellen.', 'E3: Kurze Ausstellungserklärung und ausführlicheres Fachprotokoll tatsächlich formulieren.', 'E4: Formwahl, Unsicherheit und Grenzen bei Enthalpie/ewiger Kühlung explizit reflektieren.'],
 ['E1: Transfer both full series and probe uncertainty without transposition.', 'E2: Produce time plots with common scales, units and lines identified as connections.', 'E3: Actually formulate a short exhibition explanation and a fuller technical record.', 'E4: Reflect explicitly on format, uncertainty and limits on enthalpy/permanent cooling.'],
 'Für eine frische Wiederholung fehlt der30-s-Wert. Zeige die Lücke transparent und entscheide ohne Muster, wie eine Kurzfassung trotzdem sachlich bleibt.',
 'A fresh repeat lacks the30-s reading. Show the gap transparently and independently decide how to keep a short version accurate.',False)

# 05 Raw material to industrial production to application.
case(5,'a','Steinsalz bis zum Speisesalz','Rock salt to table salt',
 'Eigenes vereinfachtes Prozessdossier: Lagerstätte enthält NaCl mit Sand/Ton. Wasser löst NaCl zur Sole; Feststoffe werden abgesetzt/gefiltert. Gereinigte Sole wird unter kontrolliertem Verdampfen konzentriert, NaCl kristallisiert, Kristalle werden getrennt und getrocknet. Speisesalzqualität erfordert zusätzliche Qualitätskontrolle; Streusalz hat andere Spezifikationen. Daten einer Modellcharge:100 kg NaCl im Rohstoff,90 kg nach Abtrennung zurückgewonnen; Energiebedarf nicht angegeben.',
 'Original simplified process dossier: deposit contains NaCl and sand/clay. Water dissolves NaCl as brine; solids settle/filter. Purified brine is concentrated by controlled evaporation, NaCl crystallises, crystals are separated and dried. Food-grade quality needs additional checks; deicing salt has different specifications. Model batch:100 kg NaCl initially,90 kg recovered; energy use unspecified.',
 'Papieraufgabe, keine Gewinnung im Gelände. Verwende Prozesskarten als gegebene industrielle Modellbeschreibung. Kennzeichne ausgelassene Reinigungsschritte und Qualitätsprüfungen; keine automatisch lebensmitteltaugliche Schulprobe behaupten.',
 'Paper task, no field extraction. Treat process cards as the supplied industrial model. Mark omitted purification and quality checks; do not claim a school sample is automatically food-grade.',
 'Zeichne eine nachvollziehbare Kette Lagerstätte→Gewinnung→Aufbereitung→Produkt→zwei Verwendungen. Erkläre für jeden Trennschritt die Stoffeigenschaft und die Bedeutung einer Qualitätsanforderung. Was folgt aus90 kg Rückgewinnung und was nicht?',
 'Draw a clear chain deposit→extraction→processing→product→two uses. Explain the property behind each separation and the importance of one quality requirement. What follows from90 kg recovery and what does not?',
 'Löslichkeit ermöglicht Solegewinnung; unlösliche Anteile werden mechanisch getrennt; Wasserentzug führt zur Kristallisation.90% beziehen sich auf rückgewonnenes NaCl, nicht automatisch auf Produktreinheit. Speise- und Streusalz benötigen verschiedene Spezifikationen. Ohne Energie-/Emissionsdaten kein vollständiges Umwelturteil.',
 'Solubility permits brine extraction; insoluble matter is mechanically separated; water removal produces crystallisation.90% refers to NaCl recovery, not product purity. Table and deicing salts need different specifications. Missing energy/emissions data prevent a full environmental judgement.',
 ['E1: Rohstoff, Sole und kristallines Produkt eindeutig unterscheiden.', 'E2: Lösen, Feststoffabtrennung und Kristallisation in begründeter Reihenfolge darstellen.', 'E3: Zwei Nutzungen mit konkreten Qualitätsanforderungen verbinden.', 'E4:90% Rückgewinnung korrekt deuten und Reinheit/Umweltbilanz als ungeklärt belassen.'],
 ['E1: Distinguish raw material, brine and crystalline product.', 'E2: Present dissolution, solid separation and crystallisation in justified order.', 'E3: Connect two uses to specific quality requirements.', 'E4: Interpret90% recovery correctly and leave purity/environmental balance unresolved.'],
 'Neu stammt die Sole aus einem bereits gelösten unterirdischen Vorkommen. Passe die Kette eigenständig an; ersetze den Rohstoffschritt, ohne Kristallisation oder Qualitätskontrolle zu streichen.',
 'Fresh brine comes from an already dissolved underground deposit. Adapt the chain independently, changing extraction without dropping crystallisation or quality control.',False)
case(5,'b','Eisenerz bis zum Bauteil','Iron ore to a structural component',
 'Vereinfachte eigene Industriekarten: Eisenerz enthält Eisenoxide und Begleitminerale. Aufbereitung erhöht den Erzanteil. Im Hochofen reduziert CO Eisenoxide; Modellgleichung Fe2O3+3CO→2Fe+3CO2. Kalkhaltige Zuschläge binden Begleitstoffe in Schlacke. Roheisen enthält viel Kohlenstoff; im Stahlwerk wird dessen Gehalt gezielt gesenkt und eingestellt. Walzen/Formen liefert Bauteile. Daten: zwei Stähle mit unterschiedlichem Korrosionsschutz; kein pauschaler Festigkeitswert vorgegeben.',
 'Original simplified industrial cards: iron ore contains iron oxides and accompanying minerals. Beneficiation increases ore fraction. CO reduces oxides in a blast furnace; model equation Fe2O3+3CO→2Fe+3CO2. Lime-bearing additions bind accompanying matter in slag. Pig iron has high carbon content; steelmaking lowers and adjusts it. Rolling/forming produces components. Data: two steels differ in corrosion protection; no universal strength supplied.',
 'Nur Prozessanalyse; keine CO-Erzeugung oder Ofenhandlung. Lies die Reaktionsgleichung als Modell der Stoffumwandlung, nicht als vollständige Hochofensimulation. Trenne Gewinnung, Stahlherstellung und Formgebung.',
 'Process analysis only; no CO production or furnace activity. Treat the equation as a model of transformation, not a complete blast-furnace simulation. Separate extraction, steelmaking and forming.',
 'Erstelle eine Stoff-/Prozesskette mit Erz, Reduktionsmittel, Nebenprodukt, Roheisen, Stahl und Bauteil. Begründe, warum Erz nicht einfach zu einem Träger gewalzt wird. Verbinde eine Außenanwendung mit Korrosionsschutz. Nenne eine fehlende Information für eine Nachhaltigkeitsbewertung.',
 'Create a material/process chain including ore, reducing agent, by-product, pig iron, steel and component. Explain why ore cannot simply be rolled into a beam. Connect an outdoor application to corrosion protection. Name information missing for sustainability assessment.',
 'Oxidisches Erz wird chemisch zum Metall reduziert; Aufbereitung und Schlacke trennen Begleitstoffe. Roheisen ist nicht fertiger Baustahl: Zusammensetzung wird eingestellt und das Material geformt. Die Gleichung erhält2Fe,3O und3C, CO2 ist Nebenprodukt. Außennutzung erfordert passenden Schutz und Werkstoffeigenschaften. Energiequelle, Emissionen, Lebensdauer und Recyclingquote fehlen.',
 'Oxidic ore is chemically reduced to metal; beneficiation and slag separate accompanying matter. Pig iron is not finished structural steel: composition is adjusted and material formed. The equation conserves2Fe,3O and3C; CO2 is a by-product. Outdoor use needs appropriate protection/properties. Energy source, emissions, lifespan and recycling rate are missing.',
 ['E1: Erz/Eisenoxid, Metall, Roheisen und Stahl stofflich korrekt unterscheiden.', 'E2: Gewinnung und weitere Verarbeitung mit der gegebenen Reaktion logisch verbinden.', 'E3: Anwendung über Eigenschaft und Korrosionsanforderung begründen.', 'E4: Nebenprodukte und Modellgrenzen benennen; keine unbelegte Gesamtumweltwertung.'],
 ['E1: Correctly distinguish ore/oxide, metal, pig iron and steel.', 'E2: Link extraction and processing logically using the supplied reaction.', 'E3: Justify application via property and corrosion requirement.', 'E4: Name by-products and model limits without an unsupported overall environmental claim.'],
 'Neues Ausgangsmaterial ist sortierter Stahlschrott statt Oxiderz. Entwickle eine eigene angepasste Kette und erkläre, weshalb Reduktion jetzt nicht derselbe notwendige Schritt ist, Sortierung aber wichtig bleibt.',
 'Fresh feedstock is sorted steel scrap rather than oxide ore. Develop an adapted chain and explain why reduction is no longer the same necessary step while sorting remains important.',False)

# 06 Isolation and purification: recovery is never silently substituted for purity.
case(6,'a','Salz aus Sandgemisch zurückgewinnen','Recover salt from a sand mixture',
 'Brille, Waage±0,01 g, Filter, Becher, Wasserbad höchstens50°C unter Aufsicht; Modellgemisch3,00 g NaCl+2,00 g Sand. NaCl ist wasserlöslich, Sand praktisch unlöslich. Lehrdaten: nach Lösen/Filtrieren/Trocknen2,70 g Kristalle; unabhängige Analyse zeigt2,565 g NaCl und0,135 g nichtflüchtige Fremdstoffe in diesen Kristallen.',
 'Goggles, balance±0.01 g, filter, beakers, supervised water bath at most50°C; model mixture3.00 g NaCl+2.00 g sand. NaCl dissolves in water; sand is essentially insoluble. Practice data:2.70 g dry crystals; independent analysis finds2.565 g NaCl and0.135 g nonvolatile impurities in them.',
 'Plane minimale ausreichende Wassermenge; löse, filtriere, spüle Sand mit kleinen dokumentierten Portionen, verdampfe Filtrat unter Aufsicht ohne Trockenheizen; lasse vollständig abkühlen und bei Raumtemperatur massenkonstant trocknen. Keine Verkostung; lokale Salz-/Sandentsorgung. Blindprobe Filter/Wasser gleich behandeln.',
 'Plan a minimal sufficient water volume; dissolve, filter, rinse sand with small recorded portions, evaporate filtrate under supervision without heating to dryness; cool and dry to constant mass at room temperature. No tasting; local salt/sand disposal. Process a filter/water blank identically.',
 'Führe das geplante Verfahren aus, protokolliere Originalmengen und Verluste und schlage eine Reinheitsprüfung vor. Berechne aus den Lehrdaten Produktreinheit und NaCl-Rückgewinnung getrennt. Entscheide, ob Filtration allein genügt.',
 'Execute the plan, record original quantities/losses and propose a purity test. Calculate product purity and NaCl recovery separately from the practice data. Decide whether filtration alone suffices.',
 'Filtration entfernt Sand, nicht gelöstes NaCl; Kristallisation trennt Wasser ab. Reinheit=2,565/2,70=95,0%; NaCl-Rückgewinnung=2,565/3,00=85,5%; bloße Produktmasse ergibt90% und ist keine reine NaCl-Ausbeute. Zu viel Waschwasser erhöht Verdampfungsaufwand; ungetrocknete Kristalle verfälschen Masse. Eigene Ausführung muss beobachtet werden.',
 'Filtration removes sand, not dissolved NaCl; crystallisation removes water. Purity=2.565/2.70=95.0%; NaCl recovery=2.565/3.00=85.5%; gross product mass gives90%, not pure NaCl yield. Excess rinse water increases evaporation demand; wet crystals distort mass. Own performance must be observed.',
 ['E1: Trennfolge aus Löslichkeit und Teilchengröße begründen.', 'E2: Eigene Filtration, sparsames Waschen und sichere Trocknung tatsächlich zeigen.', 'E3: Originalprotokoll mit Massenkonstanz, Verlustorten und Blindprobe führen.', 'E4:95,0% Reinheit und85,5% Rückgewinnung mit passenden Nennern unterscheiden.'],
 ['E1: Justify separation sequence using solubility and particle size.', 'E2: Actually demonstrate filtration, limited rinsing and safe drying.', 'E3: Keep an original record including constant mass, loss locations and blank.', 'E4: Distinguish95.0% purity and85.5% recovery using appropriate denominators.'],
 'Frisch enthält das Gemisch zusätzlich gelösten Zucker. Wähle selbst eine weitere Prüfung und erkläre, weshalb Wasserverdampfen nun keine selektive Salzreinigung garantiert.',
 'A fresh mixture additionally contains dissolved sugar. Independently choose a further test and explain why evaporating water no longer guarantees selective salt purification.')
case(6,'b','Kristallisieren gegen lösliche Verunreinigung','Crystallise against a soluble impurity',
 'Fiktives sicheres Lehrsalzmodell A: Löslichkeit30 g/100 g Wasser bei50°C und10 g/100 g bei20°C; B bleibt bei beiden Temperaturen bis50 g/100 g löslich. Charge6,00 g A+0,50 g B;20,0 g Wasser; Brille, Waage±0,01 g, Wasserbad≤50°C, Filter. Lehrdaten nach Kühlen20°C:3,60 g trockenes Produkt, Analyse3,42 g A+0,18 g B.',
 'Fictional safe teaching-salt model A: solubility30 g/100 g water at50°C and10 g/100 g at20°C; B remains soluble up to50 g/100 g at both temperatures. Batch6.00 g A+0.50 g B;20.0 g water; goggles, balance±0.01 g, bath≤50°C, filter. Practice data after cooling to20°C:3.60 g dry product, analysis3.42 g A+0.18 g B.',
 'A/B sind ausdrücklich fiktive Modellstoffe für eine reine Daten-/Planungsaufgabe, keine zum Ausführen freigegebenen Realchemikalien. Im Modell: warm lösen, langsam kühlen, kalt filtrieren, wenig kaltes Lösungsmittel zum Waschen, massenkonstant trocknen; Mutterlauge getrennt aufbewahren. Identische Temperaturen und Lösungsmittelmassen sind Kontrollbedingungen. Der tatsächliche Handlungsteil dieses Lernziels wird im vollständigen Fall lab15-06-a beobachtet.',
 'A/B are explicitly fictional model substances for a data/planning task, not real chemicals approved for execution. Model sequence: dissolve warm, cool slowly, filter cold, wash with little cold solvent, dry to constant mass; retain mother liquor separately. Equal temperatures and solvent masses are controls. Actual handling for this goal is observed in the complete case lab15-06-a.',
 'Plane am vollständigen Modell die Kristallisation; berechne theoretisch abgeschiedenes A sowie Produktreinheit und Rückgewinnung. Begründe Waschen und getrennte Mutterlauge; erkläre, weshalb diese Modellrechnung für sich keine praktische Ausführung beweist.',
 'Plan crystallisation using the complete model; calculate theoretical A crystallisation, product purity and recovery. Justify washing and separate mother liquor; explain why this model calculation alone proves no practical execution.',
 'Bei50°C lösen sich6,00 g A; bei20°C bleiben2,00 g A gelöst, theoretisch4,00 g kristallisieren. B könnte vollständig gelöst bleiben, Verunreinigung ist durch Mutterlaugenreste möglich. Produktreinheit95%; A-Rückgewinnung57%; bezogen auf theoretische Kristallmasse85,5%. Diese Nenner beantworten verschiedene Fragen. Reale Verteilung/Temperatur muss geprüft werden.',
 'At50°C6.00 g A dissolves; at20°C2.00 g remains dissolved, so theoretically4.00 g crystallises. B could remain dissolved; retained mother liquor can contaminate crystals. Product purity95%; A recovery57%; relative to theoretical crystals85.5%. These denominators answer different questions. Real partitioning/temperature needs checking.',
 ['E1: Aus temperaturabhängiger Löslichkeit selektive Kristallisation statt Verdampfen aller Stoffe wählen.', 'E2: Waschen/Trocknen und sichere Planung begründen; tatsächliche Ausführung bleibt zusätzlich im Fall06-a erforderlich.', 'E3: Mutterlauge, Waschmenge, Temperatur und Trockenmasse als benötigte Protokollgrößen festlegen.', 'E4:4,00 g theoretisches A,95% Reinheit und57% A-Rückgewinnung korrekt begrenzen.'],
 ['E1: Use temperature-dependent solubility to choose selective crystallisation over evaporating everything.', 'E2: Justify washing/drying and safe planning; actual execution is additionally required in case06-a.', 'E3: Specify mother liquor, wash volume, temperature and dry mass as required record items.', 'E4: Correctly bound4.00 g theoretical A,95% purity and57% A recovery.'],
 'Im frischen Modell fällt auch die Löslichkeit von B beim Kühlen stark. Entscheide ohne Methodenvorgabe, ob Kristallisation noch ausreichend selektiv ist, und entwirf eine unterscheidende Reinheitsprüfung.',
 'In the fresh model B solubility also falls strongly on cooling. Independently decide whether crystallisation remains selective and devise a discriminating purity test.',False)

# 07 Analysis: mixture composition plus identity, complete standards and blanks.
case(7,'a','Gemisch aus Eisen, Salz und Sand analysieren','Analyse iron, salt and sand',
 'Lehrkraftgeprüftes Modellgemisch:5,00 g aus Eisenkörnchen, NaCl und gewaschenem Sand. Brille, Magnet in Hülle, Wasser, Filter, Waage±0,01 g. Standards: Eisen magnetisch; NaCl wasserlöslich/nichtmagnetisch; Sand unlöslich/nichtmagnetisch. Fiktive getrennte Trockenmassen: Eisen1,20 g, Sand1,50 g, Salz2,20 g. Gesamtrückgewinnung4,90 g; Herkunft der fehlenden0,10 g unbekannt.',
 'Teacher-assessed model mixture:5.00 g iron granules, NaCl and washed sand. Goggles, wrapped magnet, water, filter, balance±0.01 g. Standards: iron magnetic; NaCl soluble/nonmagnetic; sand insoluble/nonmagnetic. Fictional separated dry masses: iron1.20 g, sand1.50 g, salt2.20 g. Total recovery4.90 g; missing0.10 g has unknown composition.',
 'Vorproben mit Standards und leerer Magnethülle. Eisen trocken abtrennen; Rest mit dokumentiertem Wasser lösen/filtrieren; Sand und Salzfraktion getrennt unter erlaubten Bedingungen trocknen und wägen. Körnchen statt einatembarer Pulver; kein Feuer, keine Geschmacksprobe. Lokale Abfallsammlung; Massenkonstanz prüfen.',
 'Pretest standards and empty magnet wrapper. Remove iron dry; dissolve/filter remainder with recorded water; separately dry and weigh sand and salt fractions under permitted conditions. Use granules rather than inhalable powders; no flame or tasting. Collect waste locally and check constant mass.',
 'Wähle und führe die Analyse aus. Weise Komponenten qualitativ begründet zu, berechne aus Lehrdaten wiedergewonnene Anteile am Ausgangsgemisch und prüfe die Bilanz. Darf die fehlende Masse einfach Salz genannt werden?',
 'Select and execute the analysis. Justify qualitative component assignments, calculate recovered fractions relative to the starting mixture and check the balance. May the missing mass simply be called salt?',
 'Reihenfolge nutzt Magnetismus und Löslichkeit. Wiedergewonnene Anteile am Ausgangsgemisch:24%,30%,44%; Summe98%,2% Verlust. Normalisierung auf4,90 g ergäbe nur Zusammensetzung der Rückgewinnung, nicht sichere Ausgangsanteile. Verlust könnte aus jeder Fraktion stammen; Massenbilanz begrenzt Genauigkeit. Identität gilt nur innerhalb des deklarierten Dreistoffmodells.',
 'Sequence uses magnetism and solubility. Recovered fractions of starting mass:24%,30%,44%; total98%,2% loss. Normalising to4.90 g describes recovered material, not exact starting proportions. Any fraction could contribute to the loss; mass balance limits accuracy. Identity holds only within the declared three-component model.',
 ['E1: Analyse aus unterscheidenden Eigenschaften und Standards auswählen.', 'E2: Magnettrennung, Filtration und quantitative Übertragung sicher tatsächlich ausführen.', 'E3: Fraktionen und Einheiten dokumentieren;24/30/44% und98% Bilanz korrekt berechnen.', 'E4: Identitätsbereich und unbekannte Verlustverteilung ausdrücklich begrenzen.'],
 ['E1: Select analysis from discriminating properties and standards.', 'E2: Actually execute magnetic separation, filtering and quantitative transfer safely.', 'E3: Record fractions/units and correctly calculate24/30/44% and98% balance.', 'E4: Explicitly bound identity scope and unknown distribution of losses.'],
 'Neu enthält die Probe ein zweites wasserlösliches Salz. Entwickle eigenständig die Zusatzprüfung, die nötig wäre, bevor der ganze lösliche Rückstand NaCl heißen darf.',
 'A fresh sample contains a second soluble salt. Independently devise the additional test needed before calling the whole soluble residue NaCl.')
case(7,'b','Unbekannten Reinstoff mit Referenzen identifizieren','Identify a pure unknown with references',
 'Deklarierte sichere Kandidaten: Kochsalz, Saccharose, gewaschener Quarzsand. Je1,00 g in20,0 mL Wasser bei20°C. Referenzen: NaCl klar gelöst/Leitfähigkeit8–12 mS/cm; Saccharose klar gelöst/<0,05 mS/cm; Sand Rückstand/<0,05 mS/cm. Wasserblindwert0,005 mS/cm. Fiktiv unbekannt U: klar/9,8 und10,1 mS/cm; V: Rückstand/0,008 mS/cm. Brille, Zylinder, Leitfähigkeitsgerät; kein Verzehr.',
 'Declared safe candidates: sodium chloride, sucrose, washed quartz sand. Each1.00 g in20.0 mL water at20°C. References: NaCl clear solution/conductivity8–12 mS/cm; sucrose clear/<0.05 mS/cm; sand residue/<0.05 mS/cm. Water blank0.005 mS/cm. Fictional unknown U: clear/9.8 and10.1 mS/cm; V: residue/0.008 mS/cm. Goggles, cylinder, conductivity meter; no consumption.',
 'Blindwert prüfen, Sensor spülen, gleiche Temperatur/Konzentrationsansätze verwenden. Erst Löslichkeit prüfen, dann Leitfähigkeit; zwei unabhängige Probenaliquote messen. Lehrkraft gibt nur die drei geprüften Kandidaten aus. Probenetikett und Wiederholungen dokumentieren; Lösungen örtlich entsorgen.',
 'Check blank, rinse sensor and use equal temperature/concentration preparations. Test solubility first, then conductivity; measure two independent aliquots. Teacher supplies only the three assessed candidates. Record sample label and repeats; dispose locally.',
 'Entwirf einen Entscheidungsbaum und identifiziere U/V anhand der Lehrdaten. Führe später eine frisch codierte Probe selbst aus. Begründe, weshalb „klar“ allein keinen Stoff identifiziert und warum diese Prüfung keine exakte Reinheitszahl liefert.',
 'Construct a decision tree and identify U/V from practice data. Later test a freshly coded sample yourself. Explain why clarity alone does not identify a material and why these tests do not give exact purity.',
 'U passt im Kandidatenraum zu NaCl, V zu Sand. Saccharose und NaCl sehen gelöst beide klar aus; Leitfähigkeit unterscheidet sie hier. U-Mittel9,95 mS/cm; Streuung0,3 mS/cm ist keine vollständig bestimmte Geräteunsicherheit. Andere ionische Stoffe könnten außerhalb des Kandidatenraums gleich reagieren. Kein analytischer Reinheitsprozentsatz ohne geeignete quantitative Kalibrierung.',
 'Within the candidate set U matches NaCl and V sand. Dissolved sucrose and NaCl both look clear; conductivity distinguishes them here. U mean9.95 mS/cm; a0.3 mS/cm spread is not a full instrument uncertainty. Other ionic materials outside the set could behave similarly. No purity percentage without suitable quantitative calibration.',
 ['E1: Komplementäre Verfahren anhand Kandidaten und Blindwert auswählen.', 'E2: Frisch codierte Probe ohne Kontamination selbst messen und protokollieren.', 'E3: U/V begründet zuordnen und9,95 mS/cm korrekt auswerten.', 'E4: Kandidatenraum, Messunsicherheit und fehlende quantitative Reinheitskalibrierung benennen.'],
 ['E1: Select complementary tests using candidates and blank.', 'E2: Personally measure and record a fresh coded sample without contamination.', 'E3: Justify U/V assignments and correctly obtain9.95 mS/cm.', 'E4: Name candidate-space, uncertainty and missing quantitative purity calibration.'],
 'Im frischen Kandidatensatz kommt KCl hinzu, das ebenfalls gut leitet. Wähle selbst eine zusätzliche Referenzmethode; die bisherige Zuordnung darf ohne sie nur „löslicher Elektrolyt“ lauten.',
 'Fresh candidates include KCl, also a good conductor. Independently choose an additional reference method; without it the present assignment is only “soluble electrolyte”.')

# 08 Preparation integrates planning, actual production, work-up and documentation.
case(8,'a','Hefepräparation mit kontrollierter Gasbildung','Yeast preparation with controlled gas production',
 'Bäckerhefe1,0 g je Ansatz,10,0 g Glucose in100 mL Wasser, Wasserbad30°C, zwei250-mL-Kolben mit offenem Gasabgang zu Gasspritzen, Thermometer, Brille. Kontrolle: gleicher Ansatz mit von Lehrkraft erhitzter/abgekühlter Hefe. Lehrdaten nach10/20 min: aktiv12/27 mL Gas, Kontrolle0/1 mL; Auflösung1 mL. Gasidentität wurde nicht direkt geprüft.',
 'Baker’s yeast1.0 g per batch,10.0 g glucose in100 mL water,30°C bath, two250-mL flasks with unobstructed outlets to gas syringes, thermometer, goggles. Control: identical teacher-heated/cooled yeast. Practice data at10/20 min: active12/27 mL gas, control0/1 mL; resolution1 mL. Gas identity was not directly tested.',
 'Nur unter Aufsicht, niemals druckdicht schließen; kein Trinken, keine Destillation, keine Umweltkulturen. Plane Ansatz und Kontrolle, halte Temperatur/Mengen gleich, messe Zeit/Gas, trenne nach20 min Hefe durch Filtration. Flüssigkeit ist unreines biologisches Präparat, kein reiner Ethanol. Biologische Abfälle nach Schulvorgabe beseitigen.',
 'Supervised only; never seal under pressure; no drinking, distillation or environmental cultures. Plan batch/control, keep temperature/quantities equal, measure time/gas, then filter yeast after20 min. Liquid is an impure biological preparation, not pure ethanol. Dispose of biological waste according to school rules.',
 'Führe Planung, kontrollierte Herstellung und Aufarbeitung aus und dokumentiere Originaldaten. Erkläre die Rolle lebender Hefe und den Unterschied zwischen Präparat und Reinstoff. Prüfe die Reichweite der Lehrdaten und benenne einen zusätzlichen Stoffnachweis.',
 'Execute planning, controlled preparation and work-up and record original data. Explain living yeast’s role and the distinction between preparation and pure substance. Assess the reach of practice data and name an additional chemical identification test.',
 'Aktiver Ansatz bildet mehr Gas; die Kontrolle stützt einen Zusammenhang mit aktiver Hefe. Modell der alkoholischen Gärung: C6H12O6→2C2H5OH+2CO2, aber Gasmenge allein beweist weder Gasidentität noch Ethanolreinheit; gelöstes Gas/Undichtigkeit begrenzen Mengen. Filtration trennt Hefezellen, nicht gelösten Zucker/Ethanol. Geeigneter kontrollierter CO2-Nachweis wäre ergänzend nötig.',
 'Active batch gives more gas; control supports a relationship with active yeast. Alcoholic fermentation model: C6H12O6→2C2H5OH+2CO2, but gas volume alone proves neither gas identity nor ethanol purity; dissolved gas/leaks limit quantities. Filtering removes yeast cells, not dissolved sugar/ethanol. A suitable controlled CO2 test would be additional evidence.',
 ['E1: Biotechnologische Präparation mit Hypothese und inaktivierter Kontrolle planen.', 'E2: Herstellung und Filtration tatsächlich sicher ohne Druckaufbau ausführen.', 'E3: Mengen, Temperaturen, Zeiten und Gaswerte als eigenes Protokoll festhalten.', 'E4: Gleichung als Modell und unreines Filtrat von nachgewiesenem Reinstoff unterscheiden.'],
 ['E1: Plan a biotechnological preparation with hypothesis and inactive control.', 'E2: Actually perform preparation and filtration safely without pressure build-up.', 'E3: Keep an original record of amounts, temperatures, times and gas values.', 'E4: Distinguish the equation as model and impure filtrate from identified pure substance.'],
 'Frisch wird Stärke statt Glucose angeboten. Entscheide ohne Rezeptvorgabe, ob derselbe Ansatz genügt, und plane eine Vorbehandlung samt Kontrolle, statt gleiche Gasbildung vorauszusetzen.',
 'Fresh feedstock is starch instead of glucose. Independently decide whether the same batch works and plan pretreatment plus control instead of assuming identical gas production.')
case(8,'b','Calciumcarbonat chemisch herstellen','Chemically prepare calcium carbonate',
 'Brille, Pipettierhilfe,20,0 mL0,100 mol/L CaCl2 und25,0 mL0,100 mol/L Na2CO3, Filter, Waage±0,001 g; M(CaCO3)=100,1 g/mol. Lehrdaten: trockener Niederschlag0,180 g; gereinigte Produktprobe laut unabhängiger Analyse95,0% CaCO3. Fällungsblindprobe enthält Wasser statt Carbonatlösung.',
 'Goggles, pipette aid,20.0 mL0.100 mol/L CaCl2 and25.0 mL0.100 mol/L Na2CO3, filter, balance±0.001 g; M(CaCO3)=100.1 g/mol. Practice data: dry precipitate0.180 g; independent product analysis95.0% CaCO3. Precipitation blank uses water instead of carbonate.',
 'Unter Aufsicht Lösungen nach lokalem Sicherheitsblatt handhaben; nichts probieren. Plane Reagenzüberschuss, mische langsam, filtriere, wasche mit zweimal3 mL Wasser und trockne massenkonstant bei Raumtemperatur. Filtrate getrennt sammeln; jede Übertragung und Waschmenge protokollieren.',
 'Handle solutions under supervision and local safety sheets; no tasting. Plan reagent excess, mix slowly, filter, wash twice with3 mL water and dry to constant mass at room temperature. Collect filtrates separately; record transfers and washes.',
 'Plane und führe die Synthese und Aufarbeitung selbst aus. Begründe limitierendes Edukt und Blindprobe. Berechne theoretische Produktmasse, rohe Massenausbeute und reinheitskorrigierte Ausbeute aus den Lehrdaten. Erkläre den Nutzen des Waschens.',
 'Plan and personally perform synthesis/work-up. Justify limiting reagent and blank. Calculate theoretical mass, gross mass yield and purity-corrected yield from practice data. Explain washing.',
 'Ca2++CO3^2−→CaCO3(s);2,00 mmol Ca2+ begrenzen gegenüber2,50 mmol Carbonat. Theoretisch0,2002 g; rohe Ausbeute89,9%; reines Produkt0,171 g, korrigiert85,4%. Waschen entfernt lösliche Begleitsalze; zu starkes Waschen/Übertragungsverluste können Menge senken. Ein weißer Niederschlag allein ist kein vollständiger Reinheitsnachweis.',
 'Ca2++CO3^2−→CaCO3(s);2.00 mmol Ca2+ limits against2.50 mmol carbonate. Theoretical0.2002 g; gross yield89.9%; pure product0.171 g, corrected85.4%. Washing removes soluble salts; excessive washing/transfer loss can reduce amount. White precipitate alone is not a complete purity test.',
 ['E1: Stoffmengen und limitierendes Edukt vor dem Versuch korrekt planen.', 'E2: Synthese, Waschen und Trocknen sicher tatsächlich ausführen.', 'E3: Eigenes Mengen-/Zeit-/Beobachtungsprotokoll statt Übernahme der Lehrdaten führen.', 'E4:0,2002 g,89,9% und85,4% mit jeweils erklärtem Bezug berechnen.'],
 ['E1: Correctly plan reagent amounts and limiting reagent beforehand.', 'E2: Actually perform synthesis, washing and drying safely.', 'E3: Keep original quantity/time/observation records instead of adopting practice data.', 'E4: Calculate0.2002 g,89.9% and85.4% with explained reference bases.'],
 'Neu bleibt die Carbonatmenge gleich, aber CaCl2 ist doppelt konzentriert. Entscheide selbst über den nun limitierenden Stoff und passe Produktprognose und Kontrolle an.',
 'Fresh carbonate amount stays fixed while CaCl2 concentration doubles. Independently identify the new limiting reagent and adapt the prediction/control.')

# 09 Food technique: independent practical products and biological/chemical explanation.
case(9,'a','Hefeteig kontrolliert lockern','Leaven dough with a controlled yeast process',
 'Je Ansatz50,0 g Mehl,30,0 g Wasser,1,0 g Zucker; A zusätzlich1,0 g frische Bäckerhefe, B1,0 g von Lehrkraft erhitzte/abgekühlte Hefe. Zwei gleiche transparente Becher mit Volumenmarken, Wasserbad30°C. Lehrdaten Start80 mL; nach30 min A120/124 mL in zwei Wiederholungen, B81/82 mL. Allergiehinweis Gluten; Laborprodukte nicht verzehren.',
 'Each batch:50.0 g flour,30.0 g water,1.0 g sugar; A adds1.0 g fresh baker’s yeast, B1.0 g teacher-heated/cooled yeast. Two identical clear marked cups,30°C bath. Practice data start80 mL; after30 min A120/124 mL in two repeats, B81/82 mL. Gluten allergy precaution; no consumption of laboratory products.',
 'Unter Aufsicht hygienisch mit getrennten Löffeln gleich lang kneten; offene abgedeckte Becher30 min bei30°C halten und alle10 min Volumen ablesen. Keine luftdichte Flasche, keine unbekannten Mikroben. Eigene Daten/Temperatur notieren; Werkzeuge reinigen und Teig nach Schulregel entsorgen.',
 'Under supervision use hygienic separate spoons and equal kneading times; keep loosely covered cups at30°C for30 min and read volume every10 min. No sealed bottles or unknown microbes. Record original data/temperature; clean tools and dispose by school rules.',
 'Stelle beide Teige tatsächlich her. Erkläre biologische Gasbildung und die chemisch-physikalische Rolle des Teiggerüsts beim Aufgehen. Werte Lehrdaten relativ zum Start aus; unterscheide Gasproduktion und Gasrückhalt. Begründe einen Zusatztest.',
 'Actually prepare both doughs. Explain biological gas production and the chemical/physical role of the dough network in rising. Evaluate practice data relative to start; distinguish gas production from retention. Justify an additional test.',
 'Hefe verstoffwechselt Zucker; CO2 kann sich im Teiggerüst sammeln. A-Mittel122 mL entspricht52,5% Zunahme; B81,5 mL etwa1,9%. Volumenzunahme misst nicht allein gebildetes CO2, da Gas entweichen kann und Kneten die Struktur verändert. Inaktivierte Hefe ist Kontrolle, aber Erwärmen kann weitere Eigenschaften ändern. Ein separater kontrollierter Gasansatz ergänzt die Prüfung.',
 'Yeast metabolises sugar; CO2 can accumulate in the dough network. Mean A122 mL means52.5% rise; B81.5 mL about1.9%. Rise is not a direct measure of all produced CO2 because gas escapes and kneading changes structure. Inactivated yeast is a control, but heating may change other properties. A separate controlled gas test complements it.',
 ['E1: Mengen, Zeit, Temperatur und inaktivierte Kontrolle sinnvoll festlegen.', 'E2: Lebensmitteltechnik tatsächlich hygienisch ausführen und sicher dokumentieren.', 'E3: Biologische Gärung mit Gasrückhalt im stofflichen Teiggerüst verbinden.', 'E4:52,5%/1,9% korrekt deuten und Gasproduktion nicht mit Teigvolumen gleichsetzen.'],
 ['E1: Set quantities, time, temperature and inactivated control sensibly.', 'E2: Actually perform the food technique hygienically and record it safely.', 'E3: Link biological fermentation with gas retention in the dough material.', 'E4: Interpret52.5%/1.9% correctly and avoid equating gas production with dough volume.'],
 'Frisch wird glutenfreies Mehl eingesetzt, während der Hefe-Gasansatz gleich bleibt. Plane eigenständig einen Vergleich, der verringerte Gasbildung von schlechterem Gasrückhalt unterscheidet.',
 'Fresh dough uses gluten-free flour while yeast gas production stays unchanged. Independently plan a comparison separating reduced gas production from poorer retention.')
case(9,'b','Milch mit definierter Starterkultur veredeln','Refine milk with a defined starter culture',
 'Nur schulisch freigegebene pasteurisierte Milch und kommerzieller Joghurtstarter nach Herstelleranweisung; je50 mL. A Starter, B ohne Starter, sonst gleich. Thermometer, Brille, pH-Streifen0,5er-Teilung, gleiche Becher. Fiktive Werte StartpH6,5; nach zulässiger Inkubation A4,5/dicklich, B6,5/flüssig. Kein Geschmacks- oder Verzehrversuch.',
 'Only school-approved pasteurised milk and commercial yogurt starter following manufacturer instructions;50 mL each. A with starter, B without, otherwise equal. Thermometer, goggles, pH strips with0.5 increments, identical cups. Fictional initial pH6.5; after permitted incubation A4.5/thick, B6.5/liquid. No tasting or consumption.',
 'Vor Beginn legt die Aufsicht anhand des konkreten Starterprodukts Temperatur und Inkubationszeit schriftlich fest; diese konkreten Werte ins Originalprotokoll übernehmen. Sauber arbeiten, Gefäße kennzeichnen und locker abdecken; niemals Umweltproben züchten. Start/Ende-pH mit getrennten Aliquoten bestimmen, Aussehen notieren; anschließend nach Schulhygienevorgabe entsorgen.',
 'Before work, the supervisor records temperature and incubation time for the specific starter; include those concrete values in the original record. Work cleanly, label and loosely cover vessels; never culture environmental samples. Measure initial/final pH in separate aliquots and note appearance; then dispose according to school hygiene rules.',
 'Führe die freigegebene Technik tatsächlich durch und dokumentiere die Bedingungen. Erkläre, wie bakterielle Stoffumsetzung, Säurebildung und verändertes Proteinverhalten zusammenhängen. Begründe die Kontrolle und eine Grenze der pH-Streifen.',
 'Actually perform the approved technique and record conditions. Explain the link between bacterial metabolism, acid formation and changed protein behaviour. Justify the control and one limitation of pH strips.',
 'Starterbakterien können Milchzucker zu Milchsäure umsetzen; sinkender pH verändert Wechselwirkungen der Milchproteine und begünstigt Gerinnung. pH4,5 ist nur streifenaufgelöst, kein genauer Säuregehalt. Dickwerden allein identifiziert weder Mikroben noch Produktsicherheit. Ohne Starter kann längere Lagerung trotzdem Veränderungen hervorrufen; die Kontrolle bleibt zeitlich begrenzt.',
 'Starter bacteria can convert milk sugar into lactic acid; lower pH changes protein interactions and favours coagulation. A pH4.5 strip reading is approximate, not exact acid concentration. Thickening alone identifies neither microbes nor product safety. A no-starter batch can still change on prolonged storage; control interpretation is time-bounded.',
 ['E1: Definierte Starter-/Kontrollbedingungen und Hygiene vorab festlegen.', 'E2: Präparation, pH-Probenahme und Entsorgung tatsächlich sicher ausführen.', 'E3: Biologische Umsetzung mit Säure-/Proteinänderung fachlich verknüpfen.', 'E4: Originalbeobachtung und Streifenauflösung dokumentieren; Produktsicherheit nicht aus Dicke ableiten.'],
 ['E1: Set defined starter/control conditions and hygiene beforehand.', 'E2: Actually perform preparation, pH sampling and disposal safely.', 'E3: Link biological conversion to acid/protein changes accurately.', 'E4: Record original observations and strip resolution; do not infer safety from thickness.'],
 'Frisch wird eine laktosefreie Milch derselben Proteinklasse angeboten. Entwirf eigenständig einen Vergleich; leite die Starteraktivität weder allein aus dem Wort „frei“ noch aus gleichem Aussehen ab.',
 'Fresh material is lactose-free milk of the same protein class. Independently devise a comparison; infer starter activity neither from the word “free” nor identical appearance.')

# 10 Microscopy: prepared specimens, observations and labelled original drawings.
case(10,'a','Zwiebelepidermis ohne Bildvorlage','Onion epidermis without an image cue',
 'Zwiebel, Wasser, stumpfe Pinzette, Objektträger, Deckglas, Mikroskop4×/10×/40× und Okular10×; Brille. Textreferenz: dünne Epidermis kann zusammenhängende längliche Zellen mit deutlichen Zellgrenzen zeigen; ungefärbte Zellkerne sind nicht immer erkennbar. Fremdprotokoll: bei100× zusammenhängende polygonale Felder, bei400× unscharf; rundes Gebilde wechselt beim Druck seine Lage.',
 'Onion, water, blunt forceps, slide, coverslip, microscope4×/10×/40× and10× eyepiece; goggles. Text reference: thin epidermis can show connected elongated cells with clear boundaries; unstained nuclei may be invisible. External record: connected polygonal fields at100×, blurred at400×; round feature moves when pressure changes.',
 'Unter Aufsicht sehr dünne Epidermis in Wassertropfen legen, Deckglas schräg absenken. Mit40× Gesamtvergrößerung suchen, bei100× nachfokussieren;40× Objektiv nur bei ausreichendem Abstand und Feintrieb. Keine Färbereagenzien. Glasbruch vermeiden, Präparate nach Schulvorgabe reinigen.',
 'Under supervision place very thin epidermis in a water drop and lower coverslip at an angle. Locate at40× total, refocus at100×; use40× objective only with adequate clearance and fine focus. No stains. Avoid broken glass and clean slides as instructed.',
 'Wähle, fertige und mikroskopiere ein eigenes Präparat. Erstelle eine beschriftete eigene Zeichnung mit Gesamtvergrößerung und beobachteten Merkmalen. Interpretiere Fremdprotokoll und benenne eine Artefaktprüfung. Nicht beobachtete Kerne nicht ergänzen.',
 'Select, prepare and examine an original specimen. Produce a labelled original drawing with total magnification and observed features. Interpret the external record and name an artefact check. Do not add unseen nuclei.',
 'Gesamtvergrößerung=Objektiv×Okular,10×10=100×. Dünne Probe und schräges Deckglas mindern Überlagerung/Blasen. Zellgrenzen dürfen eingezeichnet werden, wenn beobachtet; ein bewegliches rundes Gebilde kann eine Luftblase sein.400× macht ein zu dickes Präparat nicht automatisch besser. Zeichnung enthält nur sichere Merkmale und Unsicherheitsmarkierung.',
 'Total magnification=objective×eyepiece,10×10=100×. Thin sample and angled coverslip reduce overlap/bubbles. Draw observed boundaries; a moving round feature may be a bubble.400× does not automatically improve an overly thick specimen. Drawing contains only secure observations with uncertainties marked.',
 ['E1: Dünnes Wasserpräparat begründet auswählen und tatsächlich herstellen.', 'E2: Sicher fokussieren, Vergrößerung korrekt bestimmen und tatsächlich mikroskopieren.', 'E3: Eigene beschriftete Zeichnung aus beobachteten Strukturen mit Maßstabsgrenze fertigen.', 'E4: Blasen/Überlagerung prüfen und unbeobachtete Strukturen nicht als Befund ausgeben.'],
 ['E1: Justify and actually make a thin water preparation.', 'E2: Focus safely, determine magnification correctly and actually examine it.', 'E3: Make an original labelled drawing from observed structures with scale limitations.', 'E4: Check bubbles/overlap and do not report unseen structures as findings.'],
 'Eine frische Probe ist mehrfach gefaltet. Entscheide ohne Fokussierhinweis, ob größere Vergrößerung oder neue Präparation sinnvoll ist, und begründe deine Wahl anhand eigener Beobachtung.',
 'A fresh specimen is folded several times. Independently decide between increased magnification and repreparation, justifying the choice from observation.')
case(10,'b','Stärkekörner als Materialprobe','Starch granules as a material specimen',
 'Lebensmittelstärke aus Kartoffel und Mais, Wasser, Pinzette, Objektträger/Deckgläser, Lichtmikroskop und Referenzskala der Lehrkraft: bei100× entspricht1 Teilstrich10 µm. Textreferenz: Stärke liegt als einzelne Körner unterschiedlicher Form/Größe vor; Artbestimmung allein daraus ist unsicher. Fiktive Messungen ausgewählter Körner: Probe A30/40/50 µm, B10/20/20 µm; je nur drei Körner.',
 'Food-grade potato and maize starch, water, forceps, slides/coverslips, light microscope and teacher calibration: at100× one division=10 µm. Text reference: starch occurs as granules differing in shape/size; species identification from this alone is uncertain. Fictional selected granules: A30/40/50 µm, B10/20/20 µm; only three each.',
 'Brille, Staub vermeiden, kein Einatmen/Verkosten. Winzige feuchte Stärkemenge im Wassertropfen dispergieren, dünn einbetten; getrennte Geräte für beide Proben. Bei100× kalibriert messen, mindestens zehn nicht gezielt ausgewählte Körner pro eigener Probe untersuchen; Skala nur für diese Einstellung benutzen.',
 'Goggles, avoid dust, inhalation and tasting. Disperse a tiny damp starch sample in water and mount thinly; use separate tools. Measure with calibration at100×, examining at least ten nonselectively chosen granules in each own sample; scale applies only to that setting.',
 'Stelle beide Präparate her, mikroskopiere und zeichne je mehrere Körner mit Maßstab. Vergleiche Größenverteilungen statt nur eines schönsten Korns. Werte die kleinen Fremdstichproben aus und erkläre Grenzen einer Materialidentifikation.',
 'Prepare both slides, examine and draw multiple granules with scale. Compare size distributions rather than one attractive granule. Evaluate the small external samples and explain limits on material identification.',
 'A-Mittel40 µm, B etwa16,7 µm; kleine selektierte Stichproben erlauben keine sichere Verteilungs-/Artbehauptung. Fremdkörper, Überlagerung und fehlende Kalibrierung verfälschen Messung. Ein Korn ist keine ganze Zelle; die Probe ist Stoffmaterial. Beschriftung nennt Kornumriss, beobachtete Merkmale und Skala, keine erfundene Zellstruktur.',
 'Mean A40 µm, B about16.7 µm; small selected samples do not establish distributions or species. Debris, overlap and missing calibration distort measurements. A granule is not an entire cell; this is material analysis. Labels identify outline, observed features and scale, without invented cell structures.',
 ['E1: Dispersionspräparate und Kalibrierung passend zum Stoffmaterial auswählen.', 'E2: Beide Präparate selbst sicher herstellen und untersuchen.', 'E3: Originalmessungen und beschriftete Zeichnungen mit gültigem Maßstab dokumentieren.', 'E4:40/16,7 µm berechnen und Stichproben-/Identitätsgrenzen erklären.'],
 ['E1: Choose dispersion mounts and calibration appropriate to material analysis.', 'E2: Personally prepare and examine both mounts safely.', 'E3: Record original readings and labelled drawings with valid scale.', 'E4: Calculate40/16.7 µm and explain sampling/identity limits.'],
 'Ein frischer Wechsel auf400× erfolgt ohne neue Skalenkalibrierung. Entscheide eigenständig, welche bisherigen Aussagen bleiben und welche Größenangaben neu geprüft werden müssen.',
 'A fresh change to400× lacks recalibration. Independently decide which observations remain valid and which size estimates need checking.')

# 11 Living organisms: controls, welfare and actual execution, not fictional execution.
case(11,'a','Keimung und Wasserbedarf prüfen','Investigate germination and water',
 'Unbehandelter Kressesamen, je20 pro Schale, drei Schalen pro Bedingung: feuchtes Papier oder trockenes Papier; gleiche Samencharge,20°C und Licht. Lupe, Wasser, Lineal; keine Wildentnahme. Fiktiver4-Tage-Befund: feucht16/18/17 gekeimt, trocken0/1/0. Keimung definiert als sichtbare Wurzel≥2 mm.',
 'Untreated garden cress seeds,20 per dish, three dishes per condition: moist or dry paper; same seed lot,20°C and light. Magnifier, water, ruler; no wild collection. Fictional day4 result: moist16/18/17 germinated, dry0/1/0. Germination defined as visible root≥2 mm.',
 'Unter Schulaufsicht Hypothese und Keimkriterium vorab festlegen. Papier nur feucht, nicht unter Wasser; täglich gleiche Zeit zählen und Temperatur/Wasserzugabe notieren. Schimmel nicht öffnen oder weiterzüchten, Aufsicht informiert entsorgen. Samen nicht verzehren; lebende geeignete Reste nach Schulregel weiterpflegen.',
 'Under school supervision set hypothesis and germination criterion beforehand. Keep paper moist, not submerged; count at the same time daily and record temperature/water added. Do not open or propagate mould; notify supervisor for disposal. No eating seeds; continue caring for suitable live remnants by school rules.',
 'Plane, führe und dokumentiere den Vergleich tatsächlich. Werte die Fremddaten als unabhängiges Lehrbeispiel aus. Erkläre, weshalb Feuchtigkeit nicht mit Sauerstoffausschluss verwechselt werden darf, und welche Aussage über alle Pflanzen unzulässig wäre.',
 'Plan, actually conduct and document the comparison. Analyse external data as a separate teaching example. Explain why moisture must not be confused with oxygen exclusion and what generalisation to all plants would be invalid.',
 'Feucht51/60=85%, trocken1/60≈1,7%. Daten stützen Wasserbedarf unter diesen Bedingungen, nicht eine ideale Menge oder Eignung für jede Art. Überflutung kann Sauerstoff begrenzen; gleiche Samencharge und Zeit kontrollieren Alternativerklärungen. Einzelne trockene Keimung kann Restfeuchte/Variation sein. Eigene Rohdaten und Schutzverhalten müssen erst beobachtet werden.',
 'Moist51/60=85%, dry1/60≈1.7%. Data support a water requirement under these conditions, not an ideal amount or all-species rule. Flooding can limit oxygen; matched seed lot/time control alternatives. A dry germination may reflect residual moisture/variation. Original raw data and protective handling remain to be observed.',
 ['E1: Prüfbare Hypothese, unabhängige Größe Wasser und Keimkriterium definieren.', 'E2: Tatsächlich schonend durchführen; kein Wildfang oder Schimmelkultivieren.', 'E3: Wiederholungen, Wasserzugabe, Temperatur und Keimzählung original dokumentieren.', 'E4:85%/1,7% auswerten und Aussage auf Art/Bedingungen begrenzen.'],
 ['E1: Define a testable hypothesis, water as independent variable and germination criterion.', 'E2: Actually conduct carefully without wild collection or mould cultivation.', 'E3: Keep original repeats, watering, temperature and germination counts.', 'E4: Analyse85%/1.7% and limit inference to species/conditions.'],
 'Frisch soll Salzgehalt bei gleichem Wasserangebot geprüft werden. Entwickle unabhängig Verdünnungsstufen, Wasser-Kontrolle und Abbruchregel; übertrage nicht bloß die alte Trocken/Feucht-Erklärung.',
 'Fresh investigation tests salinity with equal water supply. Independently devise dilution levels, water control and a stop rule instead of merely repeating the dry/moist explanation.')
case(11,'b','Hefeaktivität bei verschiedenen Temperaturen','Yeast activity at different temperatures',
 'Bäckerhefe, Glucose, gleiche offene Gasmessansätze:1,0 g Hefe+5,0 g Glucose in50 mL Wasser;20/30/40°C, je drei Wiederholungen,10 min. Kontrolle je Temperatur ohne Zucker. Fiktive Gaswerte in mL:20°C8/9/10,30°C17/18/19,40°C10/12/11; Zuckerblindwerte0/1/0. Gasspritze1-mL-Teilung; keine direkte Enzymmessung.',
 'Baker’s yeast, glucose, equal unobstructed gas-measuring batches:1.0 g yeast+5.0 g glucose in50 mL water;20/30/40°C, three repeats each,10 min. No-sugar control at each temperature. Fictional gas volumes mL:20°C8/9/10,30°C17/18/19,40°C10/12/11; no-sugar blanks0/1/0. Syringe1-mL divisions; no direct enzyme assay.',
 'Hypothese und Zeitfenster vorab festlegen. Unter Aufsicht Temperatur mit Wasserbad kontrollieren; nie gasdicht verschließen. Gleiche Hefecharge und Startvolumina, Ansätze zufällig zuordnen, eigene Gaswerte und Undichtigkeiten notieren. Kein Trinken, keine Wildhefe-/Umweltkulturen; schulisch entsorgen.',
 'Set hypothesis/time window beforehand. Supervise temperature control with water baths; never seal gas-tight. Same yeast lot and starting volumes, randomise batches, record original gas values/leaks. No drinking, wild yeasts or environmental cultures; dispose by school rules.',
 'Führe die Untersuchung tatsächlich durch und vergleiche danach mit den Lehrdaten. Begründe die Kontrollansätze und unterscheide Nettoaktivität lebender Hefe von der Behauptung eines universellen Enzymoptimums. Erkläre eine weitere Messgrenze.',
 'Actually conduct the investigation and then compare with practice data. Justify controls and distinguish net living-yeast activity from a universal enzyme-optimum claim. Explain another measurement limitation.',
 'Mittelwerte9/18/11 mL zeigen hier größte Gasbildung bei30°C. Das ist unter drei geprüften Temperaturen das höchste Ergebnis, kein exakt bestimmtes Optimum. Enzyme, Zellzustand, Gaslöslichkeit und Lecks wirken gemeinsam;30°C darf nicht auf alle Organismen übertragen werden. Zuckerfreie Kontrolle prüft Hintergrund, nicht jede Alternativerklärung.',
 'Means9/18/11 mL show the highest gas production here at30°C. This is highest among three temperatures, not an exact optimum. Enzymes, cell state, gas solubility and leaks interact;30°C cannot be generalised to all organisms. The no-sugar control tests background, not every alternative.',
 ['E1: Temperaturhypothese, gleiche Mengen und Kontrollen begründet planen.', 'E2: Lebende Hefe tatsächlich sicher ohne Druck-/Kulturmissbrauch untersuchen.', 'E3: Wiederholungen, tatsächliche Temperatur und Gasverluste dokumentieren.', 'E4:9/18/11 mL auswerten und Messwertmaximum von allgemeinem Enzymoptimum unterscheiden.'],
 ['E1: Justifiably plan temperature hypothesis, matched amounts and controls.', 'E2: Actually investigate living yeast safely without pressure/culture misuse.', 'E3: Record repeats, actual temperatures and gas losses.', 'E4: Analyse9/18/11 mL and distinguish a measured maximum from a universal enzyme optimum.'],
 'Frisch wird der pH bei konstanter Temperatur verändert. Wähle selbst Kontrollen für pH-Messung und Hefeaktivität; die Temperaturkurve sagt das pH-Optimum nicht voraus.',
 'Fresh investigation changes pH at constant temperature. Independently choose pH and activity controls; the temperature curve does not predict a pH optimum.')

# 12 Personal-care products are school preparations, never approved medicines/cosmetics.
case(12,'a','Eine Modellcreme als Emulsion herstellen','Prepare a model cream as an emulsion',
 'Kosmetischer, schulisch freigegebener Emulgator mit dokumentierter Eignung für kaltes Anrühren; genaue Modellrezeptur pro10,0 g:2,0 g Pflanzenöl,7,5 g Wasser,0,5 g kaltverarbeitbarer Emulgator. Kontrolle2,0 g Öl+8,0 g Wasser. Waage±0,01 g, Spatel, zwei gleiche Becher, Brille. Fiktive Beobachtung nach30 min: Kontrolle zwei Phasen, Emulgatoransatz fein verteilt; keine Keim-/Langzeitstabilitätsprüfung.',
 'School-approved cosmetic emulsifier documented as suitable for cold mixing; exact model recipe per10.0 g:2.0 g vegetable oil,7.5 g water,0.5 g cold-process emulsifier. Control2.0 g oil+8.0 g water. Balance±0.01 g, spatula, identical beakers, goggles. Fictional30-min observation: control separates, emulsifier batch finely dispersed; no microbial/long-term stability test.',
 'Aufsicht prüft das konkrete Emulgatorprodukt und lokale Allergie-/Sicherheitsangaben vor Ausführung; keine Rezepturänderung durch unbekannte Tenside. Abwiegen, jeweils2 min bei Raumtemperatur mit gleicher Intensität rühren, beschriften und0/10/30 min vergleichen. Kein Auftragen, Verzehren oder Mitnehmen; keine Konservierung behaupten, schulisch entsorgen.',
 'Supervisor checks the specific emulsifier and local allergy/safety information before execution; no substitution of unknown surfactants. Weigh, stir each for2 min at room temperature with equal intensity, label and compare at0/10/30 min. No application, eating or take-home use; claim no preservation and dispose at school.',
 'Stelle Modellcreme und Kontrolle selbst her. Erkläre Öl/Wasser-Unmischbarkeit, Dispergieren und Wirkung amphiphiler Bestandteile an der Grenzfläche. Dokumentiere reale Phasentrennung und begrenze die Aussage zur Eignung als Körperpflegemittel.',
 'Personally prepare model cream and control. Explain oil/water immiscibility, dispersion and amphiphilic interfacial action. Record actual separation and limit the claim about suitability as a personal-care product.',
 'Rühren verteilt eine Phase als Tropfen, schafft aber ohne Stabilisierung keine dauerhaft homogene Lösung. Amphiphile Stoffe wechselwirken mit beiden Phasen und können Tröpfchen stabilisieren. Modellcreme ist keine neue Reinsubstanz.30-min-Stabilität ist kein Nachweis von Haltbarkeit, Hautverträglichkeit oder medizinischer Wirkung; hygienische Wasserphase kann verderben.',
 'Stirring disperses droplets but does not make a permanently homogeneous solution without stabilisation. Amphiphiles interact with both phases and can stabilise droplets. Model cream is not a new pure substance.30-min stability proves neither shelf-life, skin compatibility nor medical effects; the water phase can spoil.',
 ['E1: Rezeptur und emulsionsbezogene Kontrollprobe passend planen.', 'E2: Modellprodukt tatsächlich sicher herstellen und beschriften.', 'E3: Grenzflächenwirkung des Emulgators von bloßem Rühren fachlich unterscheiden.', 'E4: Originalzeitreihe dokumentieren und Haltbarkeit/Verträglichkeit nicht aus Stabilität ableiten.'],
 ['E1: Plan recipe and an appropriate emulsion control.', 'E2: Actually prepare and label the model product safely.', 'E3: Distinguish emulsifier interfacial action from stirring alone.', 'E4: Record an original time series and do not infer shelf-life/compatibility from stability.'],
 'Frisch soll der Ölanteil verdoppelt werden, die Gesamtmasse bleibt10 g. Wähle selbst eine neue Kontrollserie und erkläre, warum dieselbe Emulgatormenge keine gleiche Stabilität garantiert.',
 'Fresh recipe doubles oil fraction while total mass remains10 g. Independently choose a control series and explain why the same emulsifier mass does not guarantee equal stability.')
case(12,'b','Wasserfreien Modellpflegestift gießen','Cast a water-free model balm',
 'Je10,0 g Modellprodukt:3,0 g hautkontaktgeeignetes Wachs mit Schmelzbereich≤65°C,7,0 g Pflanzenöl; Vergleich2,0 g Wachs+8,0 g Öl. Brille, Waage, hitzefeste Becher, Spatel, Silikonform, thermostatiertes Wasserbad höchstens70°C nur unter unmittelbarer Aufsicht. Fiktive Druckprüfung nach24 h bei20°C mit100-g-Stempel für10 s:3-g-Wachsprobe1 mm,2-g-Probe3 mm Eindringtiefe.',
 'Each10.0 g model:3.0 g contact-grade wax with melting range≤65°C,7.0 g vegetable oil; comparator2.0 g wax+8.0 g oil. Goggles, balance, heat-resistant beakers, spatula, silicone mould, thermostatic bath at most70°C under direct supervision. Fictional indentation after24 h at20°C with100-g probe for10 s:3-g-wax sample1 mm,2-g sample3 mm.',
 'Aufsicht prüft konkrete Rohstoff-/Allergieangaben, erhitzt Wasserbad und handhabt heiße Gefäße gemeinsam mit Lernenden. Kein direktes Feuer; Spritz-/Verbrennungsrisiko beachten. Mengen wiegen, langsam schmelzen/mischen, gleich dick gießen,24 h gleich lagern. Nicht anwenden oder verzehren; keine Arznei-/Hautwirkung behaupten.',
 'Supervisor checks specific materials/allergy information, heats bath and jointly handles hot vessels. No direct flame; control splashes/burns. Weigh, slowly melt/mix, cast equal thickness and store identically24 h. Do not apply or consume; claim no medicinal/skin effect.',
 'Stelle beide Modellpflegestifte tatsächlich unter Aufsicht her. Erkläre den Unterschied zwischen Schmelzen, Mischen und chemischer Reaktion. Begründe den Wachsanteil und entwirf eine vergleichbare Festigkeitsprüfung mit eigener Dokumentation.',
 'Actually prepare both model balms under supervision. Explain melting, mixing and chemical reaction as different processes. Justify wax fraction and devise a comparable firmness test with original documentation.',
 'Wachs bildet beim Abkühlen ein festes Gerüst, Öl verändert die Konsistenz. Es liegt zunächst eine physikalische Präparation ohne belegte Synthese neuer Stoffe vor. Höherer Wachsanteil kann hier geringere Eindringtiefe ergeben; Temperatur, Stempel, Zeit und Dicke kontrollieren. Gebrauchstauglichkeit/Verträglichkeit erfordern andere Nachweise; wasserfrei bedeutet nicht automatisch keimfrei.',
 'Wax forms a solid network on cooling; oil changes consistency. This is initially physical preparation, without demonstrated synthesis of new substances. Higher wax fraction may give lower indentation here; control temperature, probe, time and thickness. Usability/compatibility need other evidence; water-free does not mean sterile.',
 ['E1: Zusammensetzung und sichere Temperaturführung begründet planen.', 'E2: Wiegen, Mischen und Gießen tatsächlich unter Heißmaterialkontrolle ausführen.', 'E3: Stoffmischung/Phasenänderung von einer unbelegten Reaktionsbehauptung unterscheiden.', 'E4: Eigene vergleichbare Prüfdaten dokumentieren und Körperverträglichkeit offenlassen.'],
 ['E1: Justifiably plan composition and safe temperature control.', 'E2: Actually weigh, mix and cast with hot-material control.', 'E3: Distinguish mixture/phase changes from an unsupported reaction claim.', 'E4: Record original comparable tests and leave bodily compatibility unproven.'],
 'Frisch soll der Stift bei30°C gelagert werden. Wähle unabhängig die Vergleichsbedingungen und erkläre, warum Daten bei20°C seine Formstabilität bei30°C nicht sichern.',
 'Fresh storage is at30°C. Independently choose comparison conditions and explain why20°C data do not guarantee shape retention at30°C.')

# 13 Materials: make, compare under equal conditions, justify an application.
case(13,'a','Gipsmischungen herstellen und prüfen','Prepare and test plaster mixtures',
 'Schulgeeigneter Modellgips mit Herstellerfreigabe; A20,0 g Gips+10,0 g Wasser, B20,0 g Gips+14,0 g Wasser, je drei gleiche40×10×5-mm-Prüfkörper. Brille, staubarmes Abwiegen, Silikonform, Waage. Fremddaten nach gleicher48-h-Lagerung: Bruchlast A8/9/10 N, B4/5/6 N; Messschritt1 N; unterschiedliche Trockenmassen nicht erhoben.',
 'School-approved modelling plaster; A20.0 g plaster+10.0 g water, B20.0 g+14.0 g water, three identical40×10×5-mm bars each. Goggles, low-dust weighing, silicone mould, balance. External data after identical48-h storage: failure load A8/9/10 N, B4/5/6 N;1-N steps; dry masses not recorded.',
 'Unter Aufsicht staubarm mischen; nie Körperteile eingipsen, Abbindung kann Wärme erzeugen. Keine Pulverinhalation, Gips nicht in Ausguss. Gleiche Formen/Füllhöhe/Lagerung; für Belastung Schutzscheibe und Auffangschale, kein Händeunterlegen. Last in1-N-Schritten mit gleicher Stützweite erhöhen; Originalbruchlast und Abweichungen notieren.',
 'Supervised low-dust mixing; never cast around body parts, as setting can release heat. Avoid inhalation; no plaster down drains. Match moulds/fill height/storage; use screen and tray for loading, keep hands clear. Increase load in1-N steps with equal support span; record original failure loads/deviations.',
 'Stelle die Prüfkörper selbst her und prüfe sie vergleichbar. Erkläre Abbindung anhand des gegebenen Modells: Halbhydrat+Wasser→Dihydrat; überschüssiges Wasser kann Poren hinterlassen. Beurteile den Einsatz als trockene Innenraumdekoration gegenüber belastetem Außenbauteil.',
 'Personally make and comparably test specimens. Explain setting using the supplied model: hemihydrate+water→dihydrate; excess water can leave pores. Assess use for dry indoor decoration versus a loaded outdoor component.',
 'CaSO4·0,5H2O+1,5H2O→CaSO4·2H2O. Mittelbruchlasten9/5 N sprechen hier für robustere A-Prüfkörper; Wasser/Gips-Verhältnis beeinflusst Porenbildung, aber Restfeuchte ist nicht gemessen. Gleiche Geometrie, Stützweite und Alter sind nötig. Keine Bauzulassung aus sechs Schulproben; Feuchte-/Dauerlastverhalten fehlt.',
 'CaSO4·0.5H2O+1.5H2O→CaSO4·2H2O. Mean loads9/5 N favour A specimens here; water/plaster ratio affects porosity, but residual moisture was not measured. Match geometry, span and age. Six school specimens give no structural certification; moisture/long-term loading remain unknown.',
 ['E1: Materialrezeptur und gleiche Prüfkörperbedingungen begründet planen.', 'E2: Herstellung und Belastung tatsächlich staub-/bruchgeschützt ausführen.', 'E3: Eigene Wiederholungen und Mittelwerte mit1-N-Auflösung dokumentieren.', 'E4: Abbindemodell, mögliche Poren und begrenzte Anwendungseignung verbinden.'],
 ['E1: Justifiably plan recipes and equal specimen conditions.', 'E2: Actually make/load specimens with dust/fracture protection.', 'E3: Record original repeats/means with1-N resolution.', 'E4: Connect setting, possible pores and bounded application suitability.'],
 'Frisch soll ein Bauteil in feuchter Umgebung dienen. Wähle selbst eine Feuchteprüfung und erkläre, warum Trockenbruchlasten das neue Kriterium nicht ersetzen.',
 'Fresh use is in a damp environment. Independently choose a moisture test and explain why dry failure loads cannot replace that criterion.')
case(13,'b','Stärkefolien mit unterschiedlicher Flexibilität','Starch films with different flexibility',
 'Je Ansatz5,0 g Lebensmittelstärke+40,0 g Wasser; A1,0 g Glycerin, B2,0 g Glycerin, beide schulisch freigegeben. Brille, Waage, Wasserbad80°C unter direkter Aufsicht, gleiche Gießfläche100 cm². Fiktive gleich getrocknete20×60-mm-Streifen: Biegeradius vor Riss A6/7/8 mm, B3/4/5 mm; Wasseraufnahme nach10 min A20%, B35% bezogen auf Trockenmasse.',
 'Each batch5.0 g food starch+40.0 g water; A1.0 g glycerol, B2.0 g, school-approved materials. Goggles, balance,80°C bath under direct supervision, equal100-cm² casting area. Fictional equally dried20×60-mm strips: bend radius before cracking A6/7/8 mm, B3/4/5 mm;10-min water uptake A20%, B35% of dry mass.',
 'Aufsicht bedient/hebt das heiße Wasserbad mit den Lernenden; kein direktes Feuer oder heißes Anfassen. Stärke in Wasser dispergieren, Glycerin zugeben, im Bad rührend verkleistern; gleichmäßig gießen und gleich lange trocknen. Dicke messen, Streifen gleich zuschneiden, Biegen und Wasseraufnahme getrennt prüfen. Nicht essen, nicht als Verpackung für Nahrung nutzen.',
 'Supervisor operates/lifts hot bath together with learners; no direct flame or touching hot surfaces. Disperse starch in water, add glycerol, gelatinise with stirring in bath; cast uniformly and dry identically. Measure thickness, cut equal strips and test bending/water uptake separately. No eating or food-contact use.',
 'Stelle beide Folien tatsächlich her. Erkläre nach dem Modell Glycerin als zwischen Ketten wirkenden Weichmacher, keine behauptete Neupolymerisation. Prüfe flexibel vs wasserbeständig als getrennte Kriterien und beurteile eine Innenraum-Abdeckung.',
 'Actually prepare both films. Explain glycerol as a between-chain plasticiser in the supplied model, without claiming new polymerisation. Test flexibility and water resistance as separate criteria and assess an indoor cover.',
 'Mehr Glycerin kann Kettenbeweglichkeit und Wasseraufnahme erhöhen. Mittelradius A7 mm/B4 mm: B lässt sich hier enger biegen. Das bedeutet keine größere Zugfestigkeit;35% Wasseraufnahme spricht gegen feuchtebelastete Nutzung. Dicke/Trocknung verfälschen Vergleich, sind daher zu kontrollieren. Keine Aussage zu industrieller Kompostierbarkeit aus diesen Daten.',
 'More glycerol can increase chain mobility and water uptake. Mean radius A7 mm/B4 mm: B bends more tightly here. This does not establish higher tensile strength;35% uptake argues against moisture exposure. Control thickness/drying because they distort comparison. These data say nothing about industrial compostability.',
 ['E1: Weichmacheranteil als Einflussgröße bei gleicher Grundrezeptur planen.', 'E2: Folien tatsächlich mit beaufsichtigter Wärmeführung herstellen.', 'E3: Dicke, Trocknung und getrennte Biege-/Wasserprüfungen original dokumentieren.', 'E4:7/4 mm und20/35% anwendungsspezifisch deuten, Zugfestigkeit nicht erfinden.'],
 ['E1: Plan plasticiser fraction as variable with equal base recipe.', 'E2: Actually make films with supervised heating.', 'E3: Record original thickness, drying and distinct bending/water tests.', 'E4: Interpret7/4 mm and20/35% by application without inventing tensile strength.'],
 'Frisch wird die Dicke verdoppelt. Plane unabhängig den Vergleich, der Materialwirkung von geometrischer Verstärkung trennt, bevor du „besserer Werkstoff“ behauptest.',
 'Fresh film thickness doubles. Independently plan a comparison separating material effects from geometry before claiming a better material.')

# 14 Ecology combines identification, field sampling and a separate manipulative lab test.
case(14,'a','Schulrasen vergleichen und Keimstandorte testen','Compare school lawns and test germination sites',
 'Zwei erlaubte Schulrasenflächen, keine Schutzfläche; drei zufällig platzierte0,25-m²-Rahmen pro Fläche, Lupe, Feuchtesensor mit0–100 relativem Index, Lichtmesser. Eigener Übungsschlüssel: parallelnervige schmale Blätter→Grasgruppe; dreiteiliges Blatt→Kleegruppe; bodennahe Rosette mit gezähntem Blatt→Löwenzahngruppe; andere Merkmale→unbestimmt. Nur Gruppen-, keine sichere Artbestimmung. Fiktive Zählungen Gras/Klee/Löwenzahn: sonnig12/4/1,14/3/2,10/5/1; schattig8/1/0,9/0/0,7/1/1. Feuchteindex sonnig30/35/32, schattig65/60/63. Labor:20 Kressesamen je Schale, je3 Schalen auf standorttypisch wenig bzw. stärker feuchtem Papier, sonst20°C und gleiches Licht.',
 'Two permitted school lawns, no protected area; three random0.25-m² quadrats per lawn, magnifier, moisture sensor0–100 relative index, light meter. Original practice key: narrow parallel-veined leaves→grass group; three leaflets→clover group; basal rosette with toothed leaf→dandelion group; other traits→unidentified. Group identification only, not secure species. Fictional grass/clover/dandelion counts: sunny12/4/1,14/3/2,10/5/1; shaded8/1/0,9/0/0,7/1/1. Moisture sunny30/35/32, shade65/60/63. Lab:20 cress seeds per dish, three dishes each with lower/higher paper moisture representative of sites, otherwise20°C/equal light.',
 'Vorab Hypothese zu Feuchte/Keimung formulieren. Unter Aufsicht nichts geschütztes sammeln; Pflanzen vor Ort mit regionaler Bestimmungsliteratur prüfen, Schlüsselgrenzen offenlegen. Rahmen zufällig platzieren, Licht/Feuchte/Zählflächen dokumentieren. Im Labor gleiche Samencharge, Wasserzugaben exakt protokollieren,4 Tage Keimung≥2-mm-Wurzel zählen; kein Schimmelzüchten oder Verzehr.',
 'Set a moisture/germination hypothesis first. Under supervision collect no protected organisms; verify plants in place using regional identification literature and disclose key limits. Randomise quadrats and record light/moisture/areas. In lab match seed lot, record exact water additions and count germination with≥2-mm root for4 days; no mould culturing or eating.',
 'Führe Freilandbestimmung/Zählung und den getrennten Keimvergleich tatsächlich durch. Charakterisiere die zwei Lebensgemeinschaften und abiotischen Bedingungen. Berechne aus Lehrdaten mittlere Grasanzahl je m². Prüfe, ob ein Feuchteunterschied allein Klee-Vorkommen erklärt und ob Kresse direkt alle Rasenarten repräsentiert.',
 'Actually conduct field identification/counting and the separate germination comparison. Characterise both communities and abiotic conditions. Calculate mean grass count per m² from practice data. Assess whether moisture alone explains clover occurrence and whether cress represents all lawn species.',
 'Gras sonnig Mittel12 pro0,25m²=48/m², schattig8=32/m². Feuchteindex ist keine Prozentwassermasse; Licht/Betritt können mitvariieren. Gruppenhäufigkeit ist nicht sichere Artenzahl, Klone erschweren Individuenzählung. Kontrollierter Kresseversuch prüft einen Faktor für diese Art, nicht Ursache der ganzen Freilandverteilung. Eignung ist art- und bedingungsspezifisch.',
 'Mean grass sunny12 per0.25m²=48/m², shade8=32/m². Moisture index is not percent water mass; light/trampling can covary. Group frequency is not secure species richness; clones complicate individual counts. Controlled cress work tests one factor for that species, not the whole field distribution. Suitability is species/condition-specific.',
 ['E1: Eigene Bestimmung mit Literatur und offengelegten Gruppen-/Artgrenzen vornehmen.', 'E2: Tatsächlich zufällig beproben und getrennten kontrollierten Keimversuch schonend durchführen.', 'E3: Gemeinschaft und abiotische Größen original dokumentieren,48/32 pro m² korrekt berechnen.', 'E4: Korrelation, manipulative Prüfung und artbezogene Lebensraumeignung getrennt begründen.'],
 ['E1: Perform original literature-based identification with disclosed group/species limits.', 'E2: Actually sample randomly and carry out a separate careful controlled germination test.', 'E3: Record community/abiotic data and correctly calculate48/32 per m².', 'E4: Separately justify correlation, manipulation and species-specific habitat suitability.'],
 'Frisch ist eine sonnige Fläche durch Bewässerung feucht. Entwickle unabhängig einen Vergleich, der Licht von Wasser trennt und gleichzeitig die Vegetation schont.',
 'A fresh sunny plot is moist through irrigation. Independently design a comparison separating light from water while protecting vegetation.')
case(14,'b','Gewässerrand beobachten und Wasserlinsen im Labor prüfen','Observe a pond edge and test duckweed in the lab',
 'Nur erlaubter sicherer Uferweg, keine Wasserentnahme aus Schutzgebieten, kein Betreten des Wassers. Beobachtung mit Fernglas/Lupe und regionalem Pflanzenführer. Eigene Gruppenmerkmale: schwimmende kleine Sprossglieder mit Wurzel→Wasserlinsengruppe; verzweigter Fadenverband ohne erkennbare Blätter→unbestimmter Algenverdacht, mikroskopisch prüfen. Fiktive Uferdaten je3 gleich große Sichtfenster: offene Stelle Deckung20/25/15%, schattige Stelle5/10/5%; Lichtwerte300/280/320 bzw.50/60/40 relative Einheiten, Temperatur22/22/23 bzw.20/20/20°C. Labor ausschließlich kommerziell bezogene Wasserlinse, gleiche definierte Nährlösung; je3 Gefäße mit10 Sprossgliedern, hell/halbschattig.',
 'Only a permitted safe bank path; no protected-site sampling or entering water. Observe with binoculars/magnifier and regional flora guide. Original group traits: small floating fronds with root→duckweed group; branched filaments without clear leaves→unconfirmed algal group needing microscopy. Fictional bank data from three equal windows: open cover20/25/15%, shaded5/10/5%; light300/280/320 versus50/60/40 relative units; temperature22/22/23 versus20/20/20°C. Lab uses only commercially supplied duckweed, equal defined nutrient solution; three vessels each with10 fronds in light/partial shade.',
 'Hypothese vorab: unter sonst gleichen Bedingungen beeinflusst Licht Sprossvermehrung. Freilandgruppen mit Literatur prüfen, unsichere Bestimmung markieren; Temperatur/Licht zeitgleich messen. Labor unter Aufsicht7 Tage bei gleicher20°C, gleichen Volumina und Startzahlen; täglich zählen, Positionen randomisieren, keine Freisetzung oder Fremdkulturen. Lokale biologische Entsorgung.',
 'Set hypothesis: with other conditions equal, light affects frond multiplication. Verify field groups with literature, mark uncertainty and measure temperature/light together. Supervised lab7 days at equal20°C, volumes and starting counts; count daily, randomise positions, no release or foreign cultures. Dispose by local biological rules.',
 'Führe sichere Freilandcharakterisierung und den getrennten Laborversuch tatsächlich aus. Erstelle Bestimmungs-/Datenprotokolle und beurteile die Licht-Hypothese aus eigenen Labordaten. Was lässt sich aus bloßer Freilanddeckung über Vermehrungsrate und Lebensraumeignung ableiten?',
 'Actually conduct safe field characterisation and the separate laboratory test. Produce identification/data records and assess the light hypothesis from original lab data. What does field cover alone establish about growth rate and habitat suitability?',
 'Freilanddeckung ist Bestandszustand, keine Vermehrungsrate; mittlere Deckung20% gegenüber≈6,7% kann auch Temperatur/Nährstoff/Strömung widerspiegeln. Labor bei konstanter Temperatur trennt Licht besser, aber nur für die verwendete Population und Lichtspanne. Literaturbestimmung bleibt bei ungenügenden Merkmalen auf Gruppenebene. Standortbeurteilung braucht mehrere Faktoren und keine Freisetzung.',
 'Field cover is a standing state, not growth rate; mean20% versus≈6.7% may also reflect temperature/nutrients/flow. Constant-temperature lab work isolates light better, but only for the population and range used. Identification remains at group level if traits are insufficient. Habitat assessment needs multiple factors and no release.',
 ['E1: Literaturgestützte Bestimmung und ungesicherte Algenzuordnung kenntlich machen.', 'E2: Freiland-/Laborhandlungen tatsächlich sicher und ohne Artverschleppung durchführen.', 'E3: Gemeinschaftsdeckung, Licht, Temperatur und eigene tägliche Labordaten getrennt dokumentieren.', 'E4:20%/6,7% als Zustand deuten; kausale Laboraussage und begrenzte Standorteignung sauber trennen.'],
 ['E1: Identify with literature and mark unconfirmed algal assignment.', 'E2: Actually conduct field/lab actions safely without spreading organisms.', 'E3: Separately record community cover, light, temperature and original daily lab counts.', 'E4: Interpret20%/6.7% as state; separate causal lab inference and bounded habitat suitability.'],
 'Frisch wird statt Licht der Nährstoffgehalt variiert. Entwickle unabhängig Kontrollen für Licht, Temperatur und Startdichte und erkläre, weshalb mehr Nährstoffe nicht automatisch für alle Gemeinschaften besser sind.',
 'Fresh manipulation changes nutrients rather than light. Independently control light, temperature and starting density and explain why more nutrients are not automatically better for every community.')

# 15 Functional systems require an actual assembly and interfaces, not just material naming.
case(15,'a','Modellwand mit Dämm- und Tragschicht','Model wall with insulation and load-bearing layers',
 'Vorbereitete schulgeeignete Gipsplatten, Korkplatten und lösungsmittelfreier Kleber, je100×100 mm; Gips5 mm, Kork5 mm. Brille, Klemmvorrichtung, Thermometer±0,5°C, geschlossene Wasserflasche40°C als Wärmequelle. Eigene Materialkarten: Gips formstabil aber spröde, Kork leicht/nachgiebig und schlechter wärmeleitend; Klebefuge kann Schichten verbinden, ist nicht automatisch feuchtebeständig. Lehrdaten nach10 min außen: Gips allein32°C; Gips+Kork25°C, Raum20°C; gleiche Innenquelle, aber keine wiederholten Messungen.',
 'Prepared school-grade plaster and cork sheets with solvent-free adhesive,100×100 mm each; plaster5 mm, cork5 mm. Goggles, clamp, thermometer±0.5°C, closed40°C water bottle as heat source. Original material cards: plaster stiff but brittle, cork light/compliant and less heat-conductive; adhesive joins layers but is not automatically moisture-resistant. Practice outer temperatures at10 min: plaster32°C, plaster+cork25°C; room20°C; same inner source but no repeats.',
 'Vorab Funktion und Kontaktflächen festlegen. Ohne Messer-/Heißkleberarbeiten zugeschnittene Teile unter Aufsicht verbinden; gleiche Klebermenge und Aushärtezeit, keine Last über Personen. Temperatur an gleicher Stelle messen, Kontakt zur Quelle kontrollieren; Werkstoffe nicht als echtes Bauteil verwenden.',
 'Set function/contact surfaces first. Under supervision join precut parts without knives/hot glue; equal adhesive and cure time, no loads above people. Measure temperature at the same point and control source contact; do not use model as a real structural component.',
 'Kombiniere die Stoffe tatsächlich zu einer Modellwand und teste gegen die Einzelschicht. Erkläre unterschiedliche Schichtfunktionen und eine kritische Schnittstelle. Begründe eine Alltag-/Technikanwendung und nenne eine nötige Zusatzprüfung.',
 'Actually combine materials into a model wall and test against one layer. Explain layer functions and a critical interface. Justify an everyday/technical use and name a needed additional test.',
 'Gips gibt Form, Kork kann Wärmetransport verzögern, Klebefuge überträgt Kräfte. Niedrigere Außentemperatur im gegebenen Zeitfenster passt zu Verzögerung, ist keine vollständige Wärmeleitfähigkeitsmessung. Mehr Gesamtdicke ist ein Mitfaktor; gleicher Dickenvergleich oder Modell macht Materialwirkung deutlicher. Feuchte, Brandverhalten, Dauerhaftigkeit und Lasten bleiben für reale Anwendung offen.',
 'Plaster supplies shape, cork can delay heat transport and adhesive transfers forces. Lower outer temperature in this interval is consistent with delay, not a full conductivity measurement. Increased total thickness is a factor; an equal-thickness comparison clarifies material effect. Moisture, fire behaviour, durability and loads remain untested for real use.',
 ['E1: Schichtfunktionen und Klebefuge als System ausdrücklich planen.', 'E2: Modell tatsächlich verbinden und kontrolliert vergleichend prüfen.', 'E3: Eigene Bedingungen/Temperaturen dokumentieren; Dicke und Kontakt als Einflussgrößen nennen.', 'E4: Anwendung über Zusammenspiel begründen und Prüfgrenzen statt Bauzulassung ausweisen.'],
 ['E1: Explicitly plan layer roles and adhesive interface as a system.', 'E2: Actually assemble and carry out a controlled comparative test.', 'E3: Record original conditions/temperatures; name thickness and contact effects.', 'E4: Justify application via interaction and report limits rather than structural approval.'],
 'Frisch soll die Modellwand außen feucht werden. Entscheide ohne Schichtmuster über Schutz und neue Fugenprüfung und begründe, weshalb Dämmwirkung allein keine Systemtauglichkeit beweist.',
 'Fresh use exposes the outer wall to moisture. Independently choose protection and an interface test and explain why insulation alone does not establish system suitability.')
case(15,'b','Filterschichten als funktionelles System','Filter layers as a functional system',
 'Zwei transparente Filtergehäuse aus vorbereiteten standsicheren Bechern, identische Filterpapiere, je20 g gewaschener Kies und20 g sauberer Sand, Auffangbecher, Brille. Testwasser nur aus Wasser+2,0 g sauberem Ton pro Liter, nicht aus Umwelt/Gewässern. Materialkarten: Kies stützt/grob verteilt, Sand hält kleinere Schwebstoffe zurück, Papier begrenzt Austrag. Lehrdaten für100 mL: Kies allein20 s/trüb; Kies+Sand+Papier90 s/deutlich klarer. Keine Keim- oder Schadstoffanalyse.',
 'Two transparent filter housings made from prepared stable cups, identical papers,20 g washed gravel and20 g clean sand each, receivers, goggles. Test water contains only water+2.0 g clean clay per litre, never environmental water. Material cards: gravel supports/distributes coarsely, sand retains smaller suspended solids, paper limits material loss. Practice for100 mL: gravel alone20 s/cloudy; gravel+sand+paper90 s/clearer. No microbial/contaminant analysis.',
 'Plane Schichtfolge, Trag-/Trennfunktion und Auslaufsicherung; Lehrkraft bereitet Gehäuse ohne scharfe Kanten. Schichten vorspülen, definierte100 mL gleich aufgeben, Zeit bis zur festgelegten100-mL-Sammelmarke messen; falls weniger durchläuft, Volumen und Abbruchzeit gesondert notieren. Niemals trinken; Sand/Kies nicht in den Abfluss.',
 'Plan layer order, support/separation roles and outlet retention; teacher supplies housings without sharp edges. Rinse layers, add defined100 mL equally, time to the specified100-mL collection mark; if less passes, record volume and stop time separately. Never drink; no sand/gravel down drains.',
 'Baue beide Systeme tatsächlich, prüfe Durchfluss und Trübung vergleichbar und dokumentiere Materialaustrag. Begründe eine technische Vorfiltration als Anwendung. Erkläre, weshalb klares Filtrat nicht automatisch Trinkwasser und langsamer nicht unter jedem Kriterium besser ist.',
 'Actually build both systems, compare flow/cloudiness and record escaping filter material. Justify technical prefiltration as an application. Explain why clear filtrate is not automatically potable and slower is not better under every criterion.',
 'Stützende grobe Schicht, feinere Trennschicht und Austragsschutz erfüllen verschiedene Aufgaben; Schnittstellen müssen Materialverlust vermeiden. Größere Rückhaltung kann den Durchfluss begrenzen;100 mL in90 statt20 s ist Zielkonflikt. Gelöste Stoffe/Keime sind nicht untersucht. Unterschiedliche Schichthöhe und Reproduzierbarkeit begrenzen Schlussfolgerung; Originalmengen und Restwasser festhalten.',
 'Coarse support, finer separation and retention paper have distinct roles; interfaces must prevent material loss. Greater retention can limit flow;100 mL in90 rather than20 s is a trade-off. Dissolved substances/microbes were not tested. Layer-height differences and repeatability limit inference; record original volumes and retained water.',
 ['E1: Materialien über unterschiedliche Funktionen und Schnittstellen zum System kombinieren.', 'E2: Beide Aufbauten tatsächlich sicher montieren und mit gleichen Bedingungen prüfen.', 'E3: Eigene Zeit-, Volumen-, Trübungs- und Austragsdaten nachvollziehbar festhalten.', 'E4: Vorfiltration fachlich begründen und Klarheit von Trinkwassersicherheit sowie Durchfluss von Trennleistung trennen.'],
 ['E1: Combine materials as a system with distinct functions/interfaces.', 'E2: Actually assemble both safely and test under matched conditions.', 'E3: Transparently record original time, volume, cloudiness and material-loss data.', 'E4: Justify prefiltration and distinguish clarity from potability and flow from separation.'],
 'Frisch enthält das Testwasser zusätzlich gelöstes Kochsalz. Wähle unabhängig eine Messgröße, die die Systemgrenze zeigt; klares Aussehen darf nicht als Salzrückhalt gelten.',
 'Fresh test water additionally contains dissolved NaCl. Independently choose a measurement revealing the system limit; clear appearance cannot count as salt retention.')

# Exact positive expectations. Observables are the corresponding concrete case rubrics.
PRINCIPLES = [
 [('Masse und Volumen brauchen passende Geräte und eindeutige Einheiten.','Mass and volume need suitable apparatus and explicit units.'),('Sachgerechtes Übertragen und Trennen ist eine beobachtbare Handlung.','Appropriate transfer and separation are observable actions.'),('Ein Originalprotokoll trennt eigene Beobachtungen von fremden Lehrdaten.','An original record distinguishes own observations from external practice data.'),('Klarheit, Stoffreinheit und Rückgewinnung sind verschiedene Aussagen.','Clarity, purity and recovery are different claims.')],
 [('Akute Beeinträchtigung und mögliche langfristige Schädigung durch Ethanol sind unterschiedliche Risiken.','Acute impairment and possible long-term harm from ethanol are distinct risks.'),('Abhängigkeit kann durch biologische, psychische und soziale Faktoren gemeinsam entstehen.','Dependence can arise through interacting biological, psychological and social factors.'),('Alltagsentscheidungen brauchen konkrete Gesundheits-, Sicherheits- und Teilhabekriterien.','Everyday decisions need explicit health, safety and inclusion criteria.'),('Herkunft, Nüchternheitsgefühl und pauschale Werbung belegen keine individuelle Sicherheit.','Origin, subjective sobriety and blanket advertising do not demonstrate personal safety.')],
 [('Fortgeschrittene Laborarbeit verbindet passende qualitative, quantitative und präparative Methoden.','Advanced laboratory work combines appropriate qualitative, quantitative and preparative methods.'),('Biologische Präparation, chemische Herstellung und Aufarbeitung verlangen tatsächliche kontrollierte Handhabung.','Biological preparation, chemical production and work-up require actual controlled handling.'),('Mengen, Kontrollen und qualitative Befunde müssen nachvollziehbar getrennt dokumentiert werden.','Amounts, controls and qualitative findings must be documented distinctly and transparently.'),('Präparat, Reinstoff und modellierte Reaktion dürfen nicht gleichgesetzt werden.','A preparation, a pure substance and a modelled reaction cannot be equated.')],
 [('Eine Darstellung muss Daten und Untersuchungsbedingungen sachlich erhalten.','A representation must accurately retain data and investigation conditions.'),('Bezugsgrößen, Einheiten, Skalierung und Unsicherheit bestimmen die lesbare Aussage.','Reference quantities, units, scaling and uncertainty determine the readable claim.'),('Adressat und Situation bestimmen die passende Form und Erklärungstiefe.','Audience and situation determine suitable form and explanation depth.'),('Die Formwahl bewahrt manche Aussagen und begrenzt andere; Beobachtung bleibt von Deutung getrennt.','Choice of form preserves some statements and limits others; observation remains distinct from interpretation.')],
 [('Rohstoff, Zwischenprodukt und gebrauchsfertiger Stoff sind verschiedene Prozessstufen.','Raw material, intermediate and usable material are distinct process stages.'),('Industrielle Gewinnung nutzt stoffbezogene Trennungen oder chemische Umwandlungen.','Industrial extraction uses material-specific separations or chemical transformations.'),('Nutzung verlangt Eigenschaften und Qualitätsanforderungen des jeweiligen Produkts.','Use depends on the product’s properties and quality requirements.'),('Rückgewinnung, Reinheit und Gesamtumweltwirkung benötigen unterschiedliche Nachweise.','Recovery, purity and overall environmental impact need different evidence.')],
 [('Isolierungsverfahren folgen Unterschieden in Löslichkeit, Teilchengröße oder Temperaturverhalten.','Isolation methods follow differences in solubility, particle size or temperature response.'),('Sichere Isolierung und Reinigung verlangen tatsächliches Trennen, Waschen und Trocknen.','Safe isolation and purification require actual separation, washing and drying.'),('Mutterlauge, Waschverluste und Feuchte müssen im Originalprotokoll sichtbar bleiben.','Mother liquor, washing losses and moisture must remain visible in the original record.'),('Reinheit und Ausbeute unterscheiden sich durch Stoffmasse und Bezugsnenner.','Purity and yield differ in component mass and reference denominator.')],
 [('Analyse braucht unterscheidende Eigenschaften, Standards und geeignete Kontrollen.','Analysis needs discriminating properties, standards and suitable controls.'),('Eine analytische Durchführung muss kontaminationsarm und tatsächlich beobachtbar sein.','Analytical execution must minimise contamination and be actually observable.'),('Qualitative Identität und quantitative Zusammensetzung verlangen nachvollziehbare Daten.','Qualitative identity and quantitative composition require transparent data.'),('Kandidatenraum, Verlustbilanz und Kalibrierung begrenzen Identitäts- und Reinheitsaussagen.','Candidate space, mass losses and calibration limit identity and purity claims.')],
 [('Herstellungsplanung verbindet biologische oder chemische Umsetzung mit passenden Kontrollen.','Preparation planning links biological or chemical transformation with suitable controls.'),('Herstellung und Aufarbeitung verlangen sichere tatsächliche Ausführung.','Production and work-up require safe actual execution.'),('Mengen, Bedingungen, Originaldaten und Verluste gehören zum Präparationsprotokoll.','Amounts, conditions, original data and losses belong in the preparation record.'),('Stoffumwandlung, Präparatreinheit und Ausbeute sind getrennt zu begründen.','Transformation, preparation purity and yield require distinct justification.')],
 [('Lebensmitteltechnik ist ein kontrolliertes Verfahren mit passender Hygiene und Vergleichsbedingung.','Food preparation is a controlled process with suitable hygiene and comparison conditions.'),('Praktisches Einsetzen einer Technik verlangt die tatsächliche Herstellung.','Practical application requires actual preparation.'),('Biologische Stoffumsetzung und chemisch-physikalische Strukturänderung erklären das Produkt gemeinsam.','Biological conversion and chemical/physical structural change jointly explain the product.'),('Volumen, pH und Aussehen sind begrenzte Messgrößen und kein Sicherheitsnachweis.','Volume, pH and appearance are limited measures, not evidence of safety.')],
 [('Probe und Fragestellung bestimmen Präparationsmethode und Kalibrierung.','Sample and question determine specimen method and calibration.'),('Mikroskopieren verlangt tatsächliche sichere Präparation und Fokussierung.','Microscopy requires actual safe preparation and focusing.'),('Beschriftete Zeichnungen müssen aus beobachteten Strukturen und gültigem Maßstab entstehen.','Labelled drawings must arise from observed structures and valid scale.'),('Artefakte, Stichprobe und Auflösung begrenzen mikroskopische Identifikation.','Artefacts, sampling and resolution limit microscopic identification.')],
 [('Hypothesengeleitete Untersuchungen brauchen vorab definierte Größen und Kontrollen.','Hypothesis-driven investigations need predefined outcomes and controls.'),('Untersuchungen an Lebewesen verlangen tatsächliches sicheres, art- und naturschutzgerechtes Handeln.','Investigations on organisms require actual safe conduct respecting species and nature protection.'),('Wiederholungen und Originalbedingungen ermöglichen eine nachvollziehbare biologische Auswertung.','Replicates and original conditions enable transparent biological analysis.'),('Ein gemessener Effekt gilt zunächst für untersuchte Organismen und Bedingungen.','A measured effect initially applies to tested organisms and conditions.')],
 [('Die Rezeptur bestimmt Phasen, Konsistenz und sichere Herstellung eines Modellpflegeprodukts.','Recipe determines phases, consistency and safe production of a model care product.'),('Herstellen ist eine tatsächliche praktische Leistung mit kontrollierten Stoff- und Temperaturbedingungen.','Preparation is actual practical performance with controlled material and temperature conditions.'),('Grenzflächen, Mischen und Phasenänderungen erklären die Zubereitung ohne erfundene Synthese.','Interfaces, mixing and phase changes explain preparation without an invented synthesis.'),('Schulische Produktmerkmale beweisen weder Hautverträglichkeit noch Haltbarkeit oder Arzneiwirkung.','School product observations establish neither skin compatibility, shelf-life nor medical effects.')],
 [('Rezeptur und gleiche Geometrie/Lagerung erlauben einen begründeten Materialvergleich.','Recipe and matched geometry/storage permit a justified material comparison.'),('Materialherstellung und Prüfung müssen tatsächlich sicher ausgeführt werden.','Material production and testing must actually be performed safely.'),('Originaldaten benötigen passende Einheiten, Wiederholungen und getrennte Prüfkriterien.','Original data need suitable units, replicates and distinct test criteria.'),('Chemische/strukturelle Eigenschaften begründen nur bedingungsspezifische Anwendungen.','Chemical/structural properties justify only condition-specific applications.')],
 [('Ökologische Charakterisierung braucht nachvollziehbare Bestimmung mit geeigneter Literatur.','Ecological characterisation needs transparent identification with suitable literature.'),('Freiland- und Laboruntersuchung benötigen tatsächliche sichere, hypothesengeleitete Durchführung.','Field and lab investigations need actual safe, hypothesis-driven conduct.'),('Lebensgemeinschaft, abiotische Größen und manipulative Labordaten sind getrennte Datensätze.','Community, abiotic factors and manipulative lab outcomes are distinct datasets.'),('Standortkorrelationen und kontrollierte Effekte tragen unterschiedliche Aussagen über Lebensraumeignung.','Site correlations and controlled effects support different habitat-suitability claims.')],
 [('Ein funktionelles System entsteht durch aufeinander abgestimmte Materialfunktionen und Schnittstellen.','A functional system arises from coordinated material roles and interfaces.'),('Kombinieren verlangt einen tatsächlich montierten und kontrolliert geprüften Aufbau.','Combination requires an actually assembled and controlled tested setup.'),('Systembeobachtungen brauchen dokumentierte Geometrie, Kontakt- und Betriebsbedingungen.','System observations need documented geometry, contact and operating conditions.'),('Anwendungseignung hängt vom Zusammenspiel und benannten Systemgrenzen ab.','Application suitability depends on interaction and explicit system limits.')],
]
for n, pairs in enumerate(PRINCIPLES,1):
    cc=[c for c in cases if c['goalId']==ids[n-1]]
    assert len(cc)==2
    exp=[]
    for k,(de,en) in enumerate(pairs):
        obs_de=' '.join(c['criterionToObservableRubric'][k]['criterionAndObservable']['de'].split(':',1)[-1].strip() for c in cc)
        obs_en=' '.join(c['criterionToObservableRubric'][k]['criterionAndObservable']['en'].split(':',1)[-1].strip() for c in cc)
        exp.append((de,en,obs_de,obs_en))
    archetype={2:'concept',4:'representation',5:'modeling'}.get(n,'experiment')
    design(n,archetype,exp,cc[0]['freshIndependentTransfer']['de']+' '+cc[1]['freshIndependentTransfer']['de'],
           cc[0]['freshIndependentTransfer']['en']+' '+cc[1]['freshIndependentTransfer']['en'])

TRANSFER_REASONING=[
 ('Zucker löst sich; Papier hält gelöste Zuckerteilchen nicht selektiv zurück. Ein Wasserblindwert und ein ungefilterter Vergleich prüfen die neue Behauptung.', 'Sugar dissolves; paper does not selectively retain dissolved sugar particles. A water blank and unfiltered comparator test the fresh claim.'),
 ('Feiner Sand setzt sich langsamer ab; Filtration kann ihn zurückhalten. Die Gerätewahl folgt der beobachteten Trübung statt einem unveränderten Abgießritual.', 'Fine sand settles more slowly; filtration can retain it. Choose apparatus from observed cloudiness instead of repeating decanting.'),
 ('Stressbewältigung und Wiederholung können einen Lern-/Verstärkungskreislauf bilden. Unterstützende alkoholfreie Wege und respektvolle professionelle Hilfe sind begründbare Maßnahmen; keine Diagnose.', 'Coping and repetition can form a learning/reinforcement cycle. Supportive alcohol-free alternatives and respectful professional help are defensible; no diagnosis.'),
 ('Ein niedrigerer Gehalt allein bestimmt weder aufgenommene Menge noch individuelle Wirkung. Gehalt, Menge, Muster und Zielgruppe fehlen; Risikofreiheit folgt nicht.', 'Lower content alone determines neither intake nor personal effects. Content, amount, pattern and audience are missing; risk-free does not follow.'),
 ('Halbe Carbonatkonzentration liefert0,50 mmol; Carbonat wird limitierend, theoretisch0,05005 g CaCO3. Nässe kann die scheinbare Masse erhöhen.', 'Half carbonate concentration supplies0.50 mmol; carbonate becomes limiting, giving0.05005 g CaCO3 theoretically. Wetness can inflate apparent mass.'),
 ('Extrakt ohne H2O2 und H2O2 ohne Extrakt sowie erhitzter Extrakt trennen Eigenschäumen von Reaktion. Gemessenes Gasvolumen ist geeigneter als Schaumhöhe, Gasidentität bleibt zu prüfen.', 'Extract without H2O2, H2O2 without extract and heated extract separate inherent foaming from reaction. Gas volume is preferable to foam height; identity still needs testing.'),
 ('Eine Überschreitung wird als >2000 µS/cm oder außerhalb des Bereichs markiert, nicht als willkürlicher Balken. Ein geeigneter neuer Bereich wäre gesondert zu messen.', 'Mark the exceedance as >2000 µS/cm or out of range rather than inventing a bar height. A suitable new range needs a separate measurement.'),
 ('Fehlender Messpunkt wird als fehlend ausgewiesen; eine Verbindung benachbarter Punkte ist keine nachträgliche Messung und muss als solche kenntlich sein.', 'Show the missing reading explicitly; connecting neighbouring points is not a retrospective measurement and must be identified accordingly.'),
 ('Sole liegt bereits vor; Lösen aus festem Erz entfällt, Reinigung/Kristallisation/Qualitätsprüfung bleiben nach Beschaffenheit erforderlich.', 'Brine already exists; dissolving solid ore is omitted, while purification, crystallisation and quality checks remain as appropriate.'),
 ('Schrott wird sortiert, gereinigt, eingeschmolzen und zusammensetzungsgeprüft; ein oxidisches Erz muss nicht erst auf dieselbe Weise reduziert werden.', 'Scrap is sorted, cleaned, melted and composition-checked; it need not first undergo the same reduction as oxide ore.'),
 ('Zucker und Salz können im Filtrat gemeinsam bleiben. Leitfähigkeit quantifiziert Zucker nicht; ein selektives geeignet kalibriertes Zusatzverfahren ist nötig.', 'Sugar and salt can remain together in filtrate. Conductivity does not quantify sugar; a selective, suitably calibrated additional method is needed.'),
 ('Wenn B ebenfalls kristallisiert, ist hohe A-Selektivität nicht gesichert. Phasenzusammensetzung oder spezifische Analyse muss die Ko-Kristallisation prüfen.', 'If B also crystallises, high selectivity for A is unproven. Phase composition or specific analysis must check co-crystallisation.'),
 ('Der lösliche Rückstand kann beide Salze enthalten. Eine Stoff-spezifische Analyse oder Trennung mit Standards ist vor einer NaCl-Massenangabe erforderlich.', 'The soluble residue may contain both salts. Substance-specific analysis or separation with standards is needed before assigning NaCl mass.'),
 ('KCl und NaCl können beide Löslichkeit/Leitfähigkeit erfüllen; ein geeigneter kalibrierter Kationen- oder Elementnachweis mit Referenzen muss zusätzlich unterscheiden.', 'KCl and NaCl can both match solubility/conductivity; a suitable calibrated cation or elemental test with references must additionally discriminate.'),
 ('Bäckerhefe setzt Stärke nicht automatisch wie freie Glucose um; eine geprüfte enzymatische Hydrolyse plus Stärke-ohne-Enzym- und Glucosekontrolle prüft die Vorbehandlung.', 'Baker’s yeast does not automatically use starch like free glucose; assessed enzymatic hydrolysis plus starch-without-enzyme and glucose controls test pretreatment.'),
 ('Ca2+ liefert4,00 mmol, Carbonat2,50 mmol und begrenzt nun. Theoretisch0,25025 g CaCO3; gleiche Blindprobe und Waschen bleiben nötig.', 'Ca2+ supplies4.00 mmol and carbonate2.50 mmol, now limiting. Theoretical CaCO3 is0.25025 g; blank and washing remain needed.'),
 ('Gleiche Hefe-Gasmengen bei verschiedenem Teigvolumen sprechen für veränderten Gasrückhalt; kontrollierte Gasmessung und gleiche Knetung trennen die Effekte.', 'Equal yeast gas amounts with different dough rise suggest changed retention; controlled gas collection and equal kneading separate effects.'),
 ('Laktosefrei kann enzymatisch gespaltenen Milchzucker bedeuten. Ob der konkrete Starter verfügbare Zucker nutzt, muss bei gleichen Protein-/Temperaturbedingungen geprüft werden.', 'Lactose-free may mean enzymatically split milk sugar. Whether the specific starter uses available sugars needs testing with matched protein/temperature conditions.'),
 ('Mehr Vergrößerung beseitigt Überlagerungen nicht. Eine dünnere neue Präparation und danach erneutes Fokussieren ist begründbar.', 'Higher magnification does not remove overlapping layers. A thinner new mount followed by refocusing is justified.'),
 ('Formbeobachtungen können bestehen bleiben; quantitative µm-Angaben brauchen die für400× gültige Kalibrierung. Die100×-Skala darf nicht unverändert benutzt werden.', 'Shape observations may remain valid; quantitative micrometre values need calibration valid at400×. Do not reuse the100× scale unchanged.'),
 ('Gleiche Wassermenge mit vorab definierten niedrigen Salzstufen und Wasserblank kontrolliert den neuen Faktor. Bei Schimmel oder deutlicher Schädigung nach Schulvorgabe stoppen.', 'Equal water with predefined low salt levels and a water blank controls the new factor. Stop for mould or clear harm under school rules.'),
 ('pH wird vor/nachher kontrolliert; gleiche Temperatur, Hefemasse und Zucker bleiben konstant. Eine separate Aktivitätskontrolle verhindert, pH-Streifenfarbe als Gasbildungsrate zu lesen.', 'Check pH before/after; keep temperature, yeast mass and sugar constant. A separate activity control avoids treating strip colour as gas-production rate.'),
 ('Öl4,0 g, Emulgator0,5 g und Wasser5,5 g ergeben10,0 g; veränderte Grenzflächen/Phasenanteile können Stabilität ändern, daher gleiche Zeit- und Rührkontrolle.', 'Oil4.0 g, emulsifier0.5 g and water5.5 g total10.0 g; altered interfaces/phase fractions can change stability, requiring matched time/stirring controls.'),
 ('Beide Rezepturen bei20 und30°C gleich lange lagern und mit gleicher Last prüfen. Schmelz-/Erweichungsverhalten hängt von Temperatur und Mischung ab.', 'Store both recipes at20 and30°C for equal times and test under equal load. Melting/softening depends on temperature and mixture.'),
 ('Gleiche Prüfkörper definiert befeuchten, Masse/Veränderung und Bruchverhalten vergleichen. Trockenfestigkeit beantwortet Wasserbeständigkeit nicht.', 'Moisten equal specimens in a defined way and compare mass/change and failure behaviour. Dry strength does not answer water resistance.'),
 ('Gleiche Dicke bei verändertem Glycerinanteil und getrennt gleiche Rezeptur bei veränderter Dicke trennen Material- und Geometrieeffekt.', 'Matching thickness across glycerol fractions and separately changing thickness at fixed recipe separates material and geometry effects.'),
 ('Ein faktorieller Vergleich hell/schattig×feucht/trocken trennt die Faktoren besser. Standortbeobachtung bleibt wegen weiterer Einflüsse begrenzt.', 'A light/shade×moist/dry factorial comparison separates factors better. Site observation remains limited by other influences.'),
 ('Nährstoffstufen bei gleicher Lichtstärke, Temperatur, Startdichte und Volumen prüfen; Gemeinschaftsfolgen können Konkurrenz/Sauerstoff umfassen, daher kein allgemeines Mehr-ist-besser.', 'Test nutrient levels at equal light, temperature, starting density and volume; community effects can involve competition/oxygen, preventing a universal more-is-better claim.'),
 ('Feuchte kann Klebefuge und Gips schwächen. Eine definierte Feuchte-/Haftungsprüfung und geeignete Schutzschicht sind neue Anforderungen unabhängig vom Temperaturversuch.', 'Moisture can weaken adhesive and plaster. Defined moisture/adhesion testing and suitable protection are new requirements independent of the thermal trial.'),
 ('Leitfähigkeit vor/nach Filtration mit Wasserblindwert zeigt, ob gelöste Ionen passieren; mechanische Klarheit weist keinen Salzrückhalt nach.', 'Conductivity before/after with a water blank tests passage of dissolved ions; mechanical clarity does not demonstrate salt retention.'),
]
