# Preserve full prerequisite/contains closure and immediate old/new context without mutation.
closure=set(ids)
queue=list(ids)
while queue:
    g=goals[queue.pop()]
    for j in g.get('requires',[])+g.get('contains',[]):
        if j not in closure: closure.add(j);queue.append(j)
neighbours={g['id'] for g in goals.values() if set(g.get('requires',[])+g.get('contains',[]))&set(ids)}
context_ids=closure|neighbours
write('source-context/full-prerequisites-and-immediate-neighbours.exact.json',{
    'canonicalInput':digest(CAN),'goalIds':ids,'requiresContainsClosureIds':sorted(closure),
    'immediateReverseRequiresAndParents':sorted(neighbours),'goals':[goals[i] for i in sorted(context_ids)]})

